export const PATHFINDER_2E_SPELL_DATA_5: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.curse-of-lost-time","name":"Curse of Lost Time","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","curse","manipulate","void"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 Large or smaller object, construct, or living creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"pEPeRZBo0RPvHAd9","formula":"4d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"pEPeRZBo0RPvHAd9":"1d6"}},"counteraction":true,"ritual":null,"description":"You curse the target with rapid aging or erosion. The effect depends on whether the target is an object, a construct, or a living creature. Artifacts, along with objects and constructs made of precious materials (as determined by the GM), are immune.\n\n- Object If the object is attended, its bearer can attempt a Fortitude save. If the bearer fails or the object is unattended, the object immediately takes 4d6 damage (applying Hardness normally) and the item is cursed with an unlimited duration. Until the curse ends, the item becomes shoddy and can't be Repaired, and the curse attempts to counteract any spell that would restore the object's Hit Points. can target an item affected by this spell.\n\n- Construct The construct takes 4d6 damage (basic Fortitude save). On a failure, for 1 hour the construct is Clumsy 1, is Enfeebled 1, and can't be Repaired, and the curse attempts to counteract any spell that would restore the construct's Hit Points. On a critical failure, these effects have an unlimited duration.\n\n- Living Creature The living creature must attempt a Fortitude save. Ageless creatures are immune.\n\n- Critical Success The living creature is unaffected.\n\n- Success The living creature briefly ages, becoming clumsy 1 and enfeebled 1 for 1 round.\n\n- Failure As success, with a duration of 1 hour.\n\n- Critical Failure As success, with an unlimited duration.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"B3eLlbaPxOYHcs1o","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cyclone-rondo","name":"Cyclone Rondo","kind":"SPELL","rank":3,"rarity":"RARE","traits":["air","concentrate","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"SQUARE","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"H4xhI890A9oH0hSx","formula":"4d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"H4xhI890A9oH0hSx":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Playing or singing melodies discovered by the ancient Shory, you call up a whirlwind. When the whirlwind appears, each creature in its area must attempt a Reflex save or be knocked . The area of the whirlwind is difficult terrain.\n\nThe whirlwind grows harsher when you Sustain the Spell, moving up to 10 feet within your range and dealing each creature whose space it enters or passes through 4d6 damage with a basic Reflex save.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"IDkEuq5jLEDhJ31C","book":"Pathfinder Wake the Dead #1","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.days-weight","name":"Day's Weight","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 living creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You fast-forward time for a single creature, burdening it with the aches and pain of an entire day and making it temporarily tired and weak. The creature must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is and Enfeebled 1 for 1 round.\n\nFailure The target is fatigued and enfeebled 1 for the duration.\n\nCritical Failure The target is fatigued and Enfeebled 2 for the duration. The fatigued condition doesn't end when the spell's duration does (but can still be removed with a night's rest or by similar means).\n\nHeightened (6th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"Llx0xKvtu8S4z6TI","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deceivers-cloak","name":"Deceiver's Cloak","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","illusion","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron drapes a cloak of illusion about you, making you appear as another creature of the same body shape with roughly similar height and weight as yourself. This has the effects of a 3rd-rank .\nHeightened (6th) You can appear as any creature of the same size, even with a completely different body shape.","source":{"provider":"PAIZO","sourceId":"FrKPwgFxWIGMGgs4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deep-sight","name":"Deep Sight","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your eyes darken until they become entirely pitch black. You grant yourself the ability to see in the darkness. You gain darkvision. If you already have darkvision, you gain greater darkvision.\n\nHeightened (7th) The duration is until the next time you make daily preparations.","source":{"provider":"PAIZO","sourceId":"Irlpzl1YBSJ6xF5e","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.delay-affliction","name":"Delay Affliction","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","manipulate","oracle","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d8","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":true,"ritual":null,"description":"With a surge of healing energy, you push back against an affliction threatening the target and grant a small amount of healing. The target recovers 3d8 Hit Points.\n\nYou attempt to counteract any one affliction you are aware the target has, suspending its effects for 1 hour on a success rather than removing it.\n\nThe target is then temporarily immune to delay affliction for 1 day. You don't need to have identified the name of the specific affliction, but you do need to be aware of it; for instance, you couldn't delay an ingested poison during its onset period unless you were aware of the poison\nHeightened (+1) The target recovers an additional 1d8 Hit Points, and you can attempt to suspend an additional affliction","source":{"provider":"PAIZO","sourceId":"ziHDISWkFSwz3pmn","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dirge-of-doom","name":"Dirge of Doom","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","concentrate","emotion","fear","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Enemies within the area are Frightened 1. They can't reduce their frightened value below 1 while they remain in the area.","source":{"provider":"PAIZO","sourceId":"1xLVcA8Y1onw7toT","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.disruptive-transfer","name":"Disruptive Transfer","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate","teleportation","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"your Speed"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Using Venorium Blorm's formulas, you calculate a path through space. Teleport to an empty square you can see within range. Creatures adjacent to your initial location witness an array of overlapping destinations. Each of them must succeed at a Will save or become for 1 minute.","source":{"provider":"PAIZO","sourceId":"jSJz4vx0fXPHa3d6","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.distracting-chatter","name":"Distracting Chatter","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You bombard a target with distracting auditory illusions, surrounding them with a tumultuous cacophony of overlapping speech, whispers, screams, and muttering. The target is , takes a -2 status penalty to purely auditory Perception checks, and must succeed at a flat to use auditory abilities or verbal spell components. Similarly, a creature who attempts to affect the target with an auditory effect must succeed at a flat or the attempt fails. The duration depends on the target's Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The duration is 1 round.\n\nFailure The duration is 3 rounds.\n\nCritical Failure The duration is 1 minute.\n\nHeightened (7th) You can target up to five creatures.","source":{"provider":"PAIZO","sourceId":"JHntYF0SbaWKq7wR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dive-and-breach","name":"Dive and Breach","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","teleportation","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"pUo5MJsp9Gefqth4","formula":"3d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"pUo5MJsp9Gefqth4":"1d10"}},"counteraction":false,"ritual":null,"description":"You make the briefest of dives through the Plane of Water. You 10 feet, and where you would land on the ground, you instead disappear in a splash of water, your body entering the surface like a diver entering a pool. You then exit from an unoccupied surface within 40 feet, appearing in another splash of water as you Leap out, landing 10 feet away from where you exited. Each splash deals 3d10 bludgeoning damage to all creatures in a ; creatures in multiple splash zones take damage only once.\n\nHeightened (+1) The damage dealt by each splash increases by 1d10.","source":{"provider":"PAIZO","sourceId":"1xM9muPRa8hiyJtI","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dividing-trench","name":"Dividing Trench","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{}},"counteraction":false,"ritual":null,"description":"You dig an earthen trench across the surrounding terrain, which must be soil, clay, sand, or other soft earth, but not flooring or stone. The trench is 5 feet wide, 5 feet deep, and up to 15 feet long. You can shape the trench's path, but it must be one continuous line. You must conjure the trench in an open space so it doesn't pass through any creatures or objects. Creatures inside the trench have cover from creatures outside the trench, and creatures outside the trench have cover from creatures inside the trench. Small or smaller creatures in the trench might have greater cover against other creatures who aren't close to the trench's edge, and in turn, those creatures might have more cover against small creatures in the trench; the GM determines the amount of additional cover, if any. Entering or leaving the trench requires an additional 5 feet of movement but doesn't require any kind of check and isn't considered difficult terrain. At the end of the spell's duration, the trench disappears, and all creatures in the trench remain in their spaces on solid ground.\nHeightened (+2) The trench's maximum length increases by 15 feet.","source":{"provider":"PAIZO","sourceId":"8OWA91bgm5r6QPaH","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dragon-breath","name":"Dragon Breath","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You spew energy from your mouth, dealing 5d6 damage with a basic Reflex save. The damage type depends on the magical tradition related to the dragon that influenced your bloodline.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"JcobNl4iE9HmMYtE","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.drain-life","name":"Drain Life","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","manipulate","sorcerer","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"3d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You close your hand and pull life energy from another creature into yourself. This deals 3d4 void damage; the target must attempt a basic Fortitude save.\n\nYou gain temporary Hit Points equal to the damage the target takes, after resolving its save and applying a blood magic effect if applicable. If the target's Hit Points were lower than the damage you dealt, you gain temporary Hit Points equal to their remaining Hit Points instead. The temporary Hit Points last for 1 minute.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"cqdmSmQnM0q6wbWG","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dream-message","name":"Dream Message","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature you know by name and have met in person","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You send a message to your target's dream. The message is one-way, up to 1 minute of speech (roughly 150 words). If the target is asleep, they receive the message instantly. If not, they receive it the next time they sleep. As soon as they receive it, the spell ends, and you know the message was sent.\n\nHeightened (4th) You can target up to 10 creatures you know by name and have met in person. You must send the same message to all of them; the spell ends for each creature individually","source":{"provider":"PAIZO","sourceId":"yM3KTTSAIHhyuP14","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.eagles-cry","name":"Eagle's Cry","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["auditory","concentrate","manipulate","sonic"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"CqsM6uCAcWDFq3dL","formula":"4d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"CqsM6uCAcWDFq3dL":"3d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You let out the mighty cry of a majestic eagle that pierces eardrums. This cry deals 4d8 sonic damage. Each creature in the area must attempt a Fortitude saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is Frightened 1.\n\nFailure The creature takes full damage and is Frightened 2.\n\nCritical Failure The creature takes double damage, is frightened 2, and is for 1 round.\nHeightened (+2) The damage increases by 3d8.","source":{"provider":"PAIZO","sourceId":"AUZPwEorddewm0x1","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.earthbind","name":"Earthbind","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 flying creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Using the weight of earth, you hamper a target's flight, with effects based on its Fortitude save. If the creature reaches the ground safely, it doesn't take falling damage.\n\nCritical Success The target is unaffected.\n\nSuccess The target falls safely up to 120 feet.\n\nFailure The target falls safely up to 120 feet. If it hits the ground, it can't Fly, levitate, or otherwise leave the ground for 1 round.\n\nCritical Failure The target falls safely up to 120 feet. If it hits the ground, it can't Fly, levitate, or otherwise leave the ground for 1 minute.","source":{"provider":"PAIZO","sourceId":"gPvtmKMRpg9I9D7H","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.echo-jump","name":"Echo Jump","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","force","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"Sh5AcM24BWIm6DOH","formula":"4d8","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Sh5AcM24BWIm6DOH":"3d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You teleport to an unoccupied space within range, leaving behind a faint echo of your form that explodes with magical force. Each creature within a 10-foot emanation from your previous location takes 4d8 force damage.\nHeightened (+2) The range increases by 10 feet, and the damage increases by 3d8.","source":{"provider":"PAIZO","sourceId":"LpMeT0CW1OEKdaQL","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.eidolons-wrath","name":"Eidolon's Wrath","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","eidolon","focus","manipulate","summoner"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Your eidolon releases a powerful energy attack that deals 5d6 damage of the type you chose when you took the Eidolon's Wrath feat, with a basic Reflex save.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"kuZnUNrhXHRYQ2eM","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.electrified-crystal-ward","name":"Electrified Crystal Ward","kind":"SPELL","rank":3,"rarity":"RARE","traits":["electricity","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"1 hinge or latch","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"You create an hazard on the target, creating a special crystalline lock on the object. You can also substitute your spell DC for any of the hazard's listed DCs. You can have only one such hazard active at a time, and if you cast this spell while a previous electric latch rune is active, the older hazard discharges harmlessly.\n\nHeightened (+2) The hazard's damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"57ulIxg3Of2wCbEh","book":"Pathfinder #148: Fires of the Haunted City","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.elemental-absorption","name":"Elemental Absorption","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You absorb elemental energy, which you can release as a powerful counterattack. Choose air, earth, fire, metal, water, or wood. You gain resistance 5 to damage dealt by effects with the chosen elemental trait; if you choose water, you also gain resistance to cold damage. As usual, if a spell has a multiple effects, such as a spell that deals both fire damage and bludgeoning damage with superheated rocks, you gain resistance to only the effects associated with the element you chose. Keep track of how much damage you have prevented with this spell.\n\nAs a 2-action activity, which has the concentrate trait and the trait matching the element you chose, you can release the stored energy. This deals damage equal to the amount you've stored (maximum 30 damage) to one enemy within 60 feet, with a basic Reflex save. The damage type depends on the element you chose: fire damage for fire; bludgeoning or cold damage for water; bludgeoning or slashing damage for air; bludgeoning, piercing, or slashing damage for earth;bludgeoning or vitality for wood; or electricity or slashing for metal. After releasing the energy, the spell ends. If you do not use the stored energy before the spell ends, the energy is lost.\n\nHeightened (+3) The resistance increases by 5 and the maximum damage increases by 30.","source":{"provider":"PAIZO","sourceId":"9TauMFkIsmvKJNzZ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-annihilation-wave","name":"Elemental Annihilation Wave","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","concentrate","earth","fire","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 to 2 rounds"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"1d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6","1":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You draw elemental power from your surroundings, and combining it with your own magical energy, unleash a wave of utter destruction and swirling colors that deals 1d6 fire damage and 3d6 bludgeoning damage with a basic Reflex save. You can replace the air trait with the metal and wood traits when you cast the spell. The number of actions you spend when Casting this Spell determines the area and other parameters.\n\n2 (somatic, verbal) The spell is a 30-foot cone.\n\n3 (material, somatic, verbal) The spell is a 30-foot cone. On a failed saving throw, creatures are pushed 5 feet away from you, and on a critical failure they are pushed 10 feet away and are knocked prone.\n\nTwo Rounds If you spend 3 actions Casting the Spell, you can avoid finishing the spell and spend another 3 actions on your next turn to empower the spell even further. If you do, the spell is as 3 actions, but the area is a , and for 1 round, the elements linger in the cone, racing off into the distance and making approaching you difficult, with the effects of .\nHeightened (+2) The damage increases by 3d6 bludgeoning and 1d6 fire, and the distance that enemies are pushed back if you spent 3 actions or 2 rounds increases by 5 feet on a failed save and 10 feet on a critical failure.","source":{"provider":"PAIZO","sourceId":"NyxQAazFBdBAqZGX","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.elemental-motion","name":"Elemental Motion","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon your element to propel you, improving your Speed depending on your element. This spell has your element's trait.\n- Air You gain a fly Speed equal to your Speed.\n- Earth You gain a burrow Speed of 10 feet.\n- Fire You gain a fly Speed equal to your Speed.\n- Metal You gain a burrow Speed of 10 feet.\n- Water You gain a swim Speed equal to your Speed and can breathe underwater.\n- Wood You gain a climb Speed equal to your Speed.\n\nHeightened (6th) You also gain a +10-foot status bonus to your Speeds.\n\nHeightened (9th) The status bonus increases to +20 feet.","source":{"provider":"PAIZO","sourceId":"B8aCUMCHCIMUCEVK","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.embrace-the-pit","name":"Embrace the Pit","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","morph","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Devil horns grow from your skull, and your skin takes on features of the devil responsible for your diabolic bloodline. You gain resistance 5 to fire and poison, and resistance 1 to physical damage (except silver).\n\nHeightened (+2) The resistance to fire and poison increase by 5, and the resistance to physical damage (except silver) by 2.","source":{"provider":"PAIZO","sourceId":"ilGsyGLGjjIPHbyP","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enthrall","name":"Enthrall","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["auditory","concentrate","emotion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"all creatures in range","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your words fascinate your targets. You speak or sing without interruption throughout the casting and duration. Targets who notice your speech or song might give their undivided attention; each target must attempt a Will save. The GM might grant a circumstance bonus (to a maximum of +4) if the target is of an opposing religion, ancestry, or political leaning, or is otherwise unlikely to agree with what you're saying.\n\nEach creature that comes within range has to attempt a save when you Sustain the spell. If you're speaking, enthrall gains the linguistic trait.\n\nCritical Success The target is unaffected and notices that you tried to use magic.\n\nSuccess The target needn't pay attention but doesn't notice you tried to use magic (it might notice others are enthralled).\n\nFailure The target is with you. It can attempt another Will save if it witnesses actions or speech with which it disagrees. If it succeeds, it's no longer fascinated and is temporarily immune for 1 hour. If the target is subject to a hostile act, or if another creature succeeds at a Diplomacy or Intimidation check against it, the fascination ends immediately.\n\nCritical Failure As failure, but the target can't attempt a save to end the fascination if it disagrees with you.","source":{"provider":"PAIZO","sourceId":"IihxWhRfpsBgQ5jS","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entropic-wheel","name":"Entropic Wheel","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","cold","concentrate","fire","psychic"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Trigger You deal cold or fire damage to an enemy.\n\nYou stockpile thermal energy in a magical wheel-like construct that lets you burn opponents with cold or freeze their bodies with heat. When you Cast the Spell, the wheel has one mote of thermal energy, and when you use a cold or fire effect or deal cold or fire damage, the wheel spins, siphoning off a bit of energy and gaining another mote. The wheel can't gain motes more than once on a given turn, and the maximum number of motes is equal to entropic wheel's rank.\n\nWhen you Cast a Spell that deals fire damage, the target also takes cold damage equal to the number of motes in the entropic wheel. When you Cast a Spell that deals cold damage, the target also takes fire damage equal to the number of motes in the entropic wheel. This applies only to the initial damage of the spell, not to any persistent damage or ongoing effects.","source":{"provider":"PAIZO","sourceId":"X4T5RlQBrdpmA35n","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.envenom-companion","name":"Envenom Companion","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your companion or eidolon","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You envenom your companion or eidolon's attacks, which drip with highly toxic venom for the spell's duration. The first time each round the target hits a creature with an unarmed Strike that deals piercing or slashing damage, that Strike deals an additional 1d8 poison damage. A creature that is damaged by this poison must attempt a Fortitude save. On a failure, it's also Clumsy 1 for 1 round. This spell can't target familiars.\n\nHeightened (+3) The poison damage increases by 1d8 and the clumsy value imposed on a failed save increases by 1.","source":{"provider":"PAIZO","sourceId":"gWmLT5SkA0qH2mNE","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ephemeral-tracking","name":"Ephemeral Tracking","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can look at currents in the air and water and see tracks that you can follow just as you would on land. You can use Survival to through both air and water, noticing aerial or aquatic \"tracks\" of all creatures who passed nearby in the last hour. It's more difficult to Track in this way: the DC to Track through air or water is always at least 30, or higher after precipitation or wind (in the air) or heavy tides or currents (in the water). It's possible to against this spell, but creatures might not realize they need to do so.","source":{"provider":"PAIZO","sourceId":"QpjHqxwTGdILLvjD","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.excise-lexicon","name":"Excise Lexicon","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reach into a creature's mind and extract its knowledge of a word. Choose a word to excise when you Cast the Spell. The word must be a mundane word, not a proper noun, and not a word of power such as those used as verbal components for spells. The target must attempt a Will save. The target forgets any words you remove with this spell. While the spell lasts, the target doesn't register or understand the excised words in any form, signed, spoken, written, or otherwise, and can't comprehend them by any means, even by a tongues spell or similar magic. The spell fails if you don't share at least one language with the target. However, the target forgets the words from each language they know, not just your shared languages.\n\nCritical Success The target is unaffected and knows which words you attempted to excise.\n\nSuccess The spell's duration is 1 minute.\n\nFailure The spell's duration is 1 day.\n\nCritical Failure The spell's duration is unlimited.\n\nHeightened (+2) You excise one additional word.","source":{"provider":"PAIZO","sourceId":"GurWFDj4IjKv73kL","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.extend-blood-magic","name":"Extend Blood Magic","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","sorcerer","spellshape"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the arcane energy coursing through your blood to extend the magic it grants. If your next action is to Cast a Spell that grants you a blood magic effect that lasts for at least 1 round, you or a target gain the blood magic effect for an additional round. You can have only one extended blood magic effect at a time.","source":{"provider":"PAIZO","sourceId":"LyqqvufOUIh8U25d","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.extend-spell","name":"Extend Spell","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","sorcerer","spellshape"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon your blood's knowledge of the ancients to extend your magic. If your next action is to Cast a Spell with a duration of 1 minute on a single target, the spell instead lasts 10 minutes. You can extend a spell only if you cast it from a spell slot lower than your highest spell slot, and you can have only one active spell at a time extended in this way.","source":{"provider":"PAIZO","sourceId":"GxxnhRIaoGKtu1iO","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.eyes-of-the-dead","name":"Eyes of the Dead","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"one undead creature under your control","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You enter a magical trance that allows you to perceive through the senses of the target creature. You attempt Perception checks using your own Perception, but you have any special senses the target has, such as low-light vision or darkvision. The spell doesn't grant any special method of communication with the target. For the duration of the trance, your own senses are muted, though you can still communicate. This lack of awareness makes you . You can't take actions with the attack or move traits, nor can you cast spells.\n\nHeightened (6th) The range increases to 100 miles and the duration to sustained up to 10 minutes. You can communicate telepathically with the target for the duration of the trance, though the target is under no compulsion to follow commands if it wasn't already.","source":{"provider":"PAIZO","sourceId":"DLFupJuCfzyLCQcO","book":"Pathfinder Book of the Dead","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.familiars-face","name":"Familiar's Face","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"1 willing creature that's your animal companion or familiar","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target becomes a scrying sensor, allowing you to see through its eyes, smell what it smells, and similarly use its other senses. If you Cast a Spell with the revelation trait that affects your senses, such as , while this spell is active, you gain the benefit of the spell through the target's senses instead of your own. You can also speak through the target with a voice much like yours, though it takes on some of the timbre and character of the target's growls or squawks. You can use Command an Animal on the target as part of Sustaining this spell. You don't need line of sight or line of effect to your target when you Cast this Spell.","source":{"provider":"PAIZO","sourceId":"9GkOWDFDEMuV3hJr","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.far-sight","name":"Far Sight","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","visual"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can see distant objects as if they were closer. You can view creatures, objects, and terrain features that are more than 30 feet away and up to 300 feet away as though they were only 30 feet away. You can view creatures, objects, and terrain features that are 300 feet away or more as though they were only one-tenth as far away. This spell only affects your ability to discern visual details; it doesn't let you treat the objects as actually closer for the purposes of spells, ranged attacks, or otherwise. This spell doesn't affect the range of other visual senses you might have, so if you have a visual sense that extends to only 60 feet, you still can't use it to see things beyond that range, even if they would appear closer with this spell.","source":{"provider":"PAIZO","sourceId":"ErCsWsqXe8ccRjgO","book":"Pathfinder #177: Burning Tundra","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fates-travels","name":"Fate's Travels","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 corpse","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You get a vision of the creature when it was alive, and its last 10 minutes of travel. This vision gives you a clear impression of the route it took and locations it visited, if any, but not any creatures or hazards in those areas. This information is enough to automatically succeed at Tracking the creature over that distance.\n\nHeightened (6th) Your vision covers the creature's last hour of travel, and you gain an impression of the hazards, creature types, and number of creatures it encountered along the way, as well as a clear impression of how it died.","source":{"provider":"PAIZO","sourceId":"e4vxRJ4sjUXMEIGP","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.feet-to-fins","name":"Feet to Fins","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's feet transform into fins, improving mobility in the water but reducing it on land. The target gains a swim Speed equal to its normal land Speed, but its land Speed becomes 5 feet.\n\nHeightened (6th) The spell lasts until your next daily preparations.","source":{"provider":"PAIZO","sourceId":"RvBlSIJmxiqfCpR9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fey-disappearance","name":"Fey Disappearance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become and ignore natural difficult terrain (such as underbrush). Any hostile action you use ends this invisibility, but you still ignore natural difficult terrain.\n\nHeightened (5th) If you use a hostile action, the invisibility doesn't end.","source":{"provider":"PAIZO","sourceId":"mBojKJatf9PTYC38","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fireball","name":"Fireball","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A roaring blast of fire detonates at a spot you designate, dealing 6d6 fire damage.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"sxQZ6yqTn0czJxVd","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.firework-blast","name":"Firework Blast","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0MD5xTKLlw8jZPKU","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0MD5xTKLlw8jZPKU":"2d6"}},"counteraction":false,"ritual":null,"description":"You create a massive display of loud and colorful explosions. The explosions deal 4d6 fire damage. Creatures that fail their saves must attempt an additional fortitude save. Creatures that critically fail their saves take a -2 circumstance penalty to this Fortitude save.\n\nSuccess The creature is unaffected.\n\nFailure The creature is and for 1 round.\n\nCritical Failure The creature is blinded for 1 round and and deafened for 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"1OiPVy1wuoXi6LR5","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.focusing-hum","name":"Focusing Hum","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You infuse the air around you with a sustained hum that allows creatures within it to resist distractions. The DC of any flat check to Cast a Spell while stupefied for creatures within the area is 2 lower. creatures in the area don't attack anyone, including themselves, and instead lose the ability to speak coherently. You take a -2 penalty to Stealth checks to and .","source":{"provider":"PAIZO","sourceId":"28kgh0JzBO6pt38C","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fungal-exhalation","name":"Fungal Exhalation","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","fungus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"frm1uBmzLuW6mwMX","formula":"6d4","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"frm1uBmzLuW6mwMX":"2d4"}},"counteraction":false,"ritual":null,"description":"You exhale toxic mold spores that fill the area. You deal 6d4 poison damage to creatures in the area. On a failure, a creature is also Sickened 1, or Sickened 2 on a critical failure. A creature that doesn't breathe is immune to this effect.\n\nHeightened (+1) The damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"H481wmQUtEUhxHzi","book":"Pathfinder #202: Severed at the Root","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.gasping-marsh","name":"Gasping Marsh","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"q8ptrzvf1kb0ms3q","formula":"4d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a rattling hiss, you create a quickly evaporating mist of invisible poisonous marsh gas to smother creatures in the area. When you Sustain the Spell, the mist dissipates completely from the previous area, and you can select a new area within range to fill with the mist. If you don't Sustain the Spell, the mist dissipates and the spell ends.\n\nYou deal 4d6 poison damage to each breathing creature that starts its turn in the area. Each affected creature must attempt a Fortitude save.\n\nThe creature is then temporarily immune to gasping marsh for 1 minute.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Sickened 1.\n\nCritical Failure The creature takes double damage, is Sickened 2, and takes 1d8[persistent,poison].","source":{"provider":"PAIZO","sourceId":"kvZCQz4NoMAfjvif","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.geas","name":"Geas","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":["curse","mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature of a level no greater than double the geas ritual's rank","area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert), Occultism (expert), or Religion (expert)","secondaryChecks":"Society or Legal Lore","secondaryCasters":1},"description":"You enforce a magic rule on a willing target, forcing it to either perform or refrain from carrying out a certain act. A geas to perform an act is usually conditional, such as, \"Always offer hospitality to strangers seeking a place to stay.\" An unconditional geas to perform a certain act doesn't require the target to perform that act exclusively, though it must prioritize the task above all leisurely pursuits. The most common geas to refrain from carrying out an act is a specification to avoid violating a contract. In those cases, the secondary caster usually takes charge of making sure the wording of the contract is attuned correctly with the ritual's magic. Because the target is willing, geas can have a duration that lasts for as long as the target agrees to. If the target is unable to fulfill the geas, it becomes Sickened 1, and the sickened condition increases by 1 for each consecutive day it is prevented from following the geas, to a maximum of sickened 4. The sickened condition ends immediately when it follows the geas again; it can't remove the sickened condition in any other way. Only powerful magic such as a ritual can remove the effects of geas from a willing target.\n\nCritical Success The geas succeeds, and the target receives a +1 status bonus to skill checks that directly uphold the geas (at the GM's discretion).\n\nSuccess The geas succeeds.\n\nFailure The geas fails.\n\nCritical Failure The geas fails, and you are instead affected by the geas you were attempting to place on the target. You are considered an unwilling target, so the geas can be counteracted with a spell.\n\nHeightened (5th) You can use geas on an unwilling creature; it can attempt a Will save to negate the effect. If the target fails this Will save, the geas lasts up to 1 week. A cleanse affliction spell can counteract a geas on an unwilling creature, in addition to powerful magic such as a wish ritual. A clever unwilling creature can subvert the geas by contriving situations that prevent it from complying, but in that case it becomes (as described above).\n\nHeightened (7th) As 5th rank, but the geas lasts for up to 1 year on an unwilling creature.\n\nHeightened (9th) As 5th rank, but the geas lasts for a duration you choose (even unlimited) on an unwilling creature.","source":{"provider":"PAIZO","sourceId":"Q690d3mw3TUrKX7E","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghostly-shift","name":"Ghostly Shift","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","concentrate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your body becomes insubstantial as you partially phase out. You gain resistance 2 to all damage (except force).\n\nHeightened (+2) The resistance increases by 1.","source":{"provider":"PAIZO","sourceId":"JqHAxsMUZ4Mr5bTr","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghostly-weapon","name":"Ghostly Weapon","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 weapon that is either unattended or wielded by you or a willing ally","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target weapon becomes translucent and ghostly, and it can affect material and incorporeal creatures and objects. It gains the effects of the property rune, meaning it is magical if it wasn't already, is especially effective against incorporeal creatures, and can be wielded by a corporeal or incorporeal creature.","source":{"provider":"PAIZO","sourceId":"AMEu5zzLN7uCX645","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glass-sand","name":"Glass Sand","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"UeqA2WmETFphNSgC","formula":"4d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"UeqA2WmETFphNSgC":"2d6"}},"counteraction":false,"ritual":null,"description":"You throw a handful of sand that transforms into jagged shards of glass. Creatures in the area take 4d6 slashing damage and must attempt a Reflex save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage and 1[bleed]{1 persistent bleed} damage.\n\nCritical Failure The target takes double damage and 2 persistent bleed damage.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"dgMauNKWeRIu8pMN","book":"Pathfinder Adventure: The Enmity Cycle","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.gravity-well","name":"Gravity Well","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":30,"text":"30-foot-radius burst"}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a sphere of altered gravity. All creatures and unsecured objects in the area move towards the center, depending on their Reflex saving throws. This follows the rules for forced movement. If there's not enough space near the center of the sphere, creatures and objects nearer to the center move first, and others move as far as they can without being blocked, up to the amount set by their saving throw outcomes.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature moves 5 feet toward the center.\n\nFailure The creature moves 15 feet toward the center.\n\nCritical Failure The creature moves 30 feet toward the center.","source":{"provider":"PAIZO","sourceId":"06pzGkKTyPE3tHR8","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.guardians-aegis","name":"Guardian's Aegis","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils worth 10 gp × the primary caster's level"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion","secondaryChecks":"Athletics, Diplomacy, or Society","secondaryCasters":1},"description":"The guardian's aegis is a ritual used across numerous cultures to bind a chosen guardian and ward together so that they can complete a quest of great import. When the ritual is completed, designate one of the casters as the guardian, while the other is the ward. As long as you're on the same plane of existence, both of you are always aware of each other's relative directions and state of being, including any conditions the other is affected by. As long as you're within 30 feet of each other, whenever the ward takes damage, the damage is reduced by the amount equal to half the guardian's level, and the guardian loses an equal number of Hit Points; the target still takes additional effects like poison even if guardian's aegis reduces the damage to 0.\n\nCritical Success The ritual is successful, and the duration is 1 month.\n\nSuccess The ritual is successful.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual backfires. You and the secondary caster become magically isolated from each other for 1 week, unable to provide each other any beneficial effect.","source":{"provider":"PAIZO","sourceId":"3ipOKanMLnJrPwbr","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.haste","name":"Haste","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Magic empowers the target to act faster. It gains the condition and can use the extra action each round only for Strike and Stride actions.\n\nHeightened (7th) You can target up to 6 creatures.","source":{"provider":"PAIZO","sourceId":"o6YCGx4lycsYpww4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hearts-desire","name":"Heart's Desire","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","emotion","focus","illusion","manipulate","mental","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround your target with wondrous illusions of their greatest desires, which distract them from reality. The target must attempt a Will save.\nCritical Success The target disbelieves the illusion and is unaffected.\n\nSuccess For 1 round, the target is Stupefied 2 and takes a -2 status penalty to any checks it makes to determine the effects of reactions.\n\nFailure For 1 minute, the target is stupefied 2 and can't use reactions.\n\nCritical Failure As failure, and all spaces are difficult terrain for the target.\nHeightened (+2) You can target one additional creature.","source":{"provider":"PAIZO","sourceId":"PVXqMko4yGgw90uo","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heatvision","name":"Heatvision","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target visually senses the heat energy emitted by the creatures and objects around it, gaining infrared vision at a range of 60 feet as a precise sense. This vision can detect any warm-blooded creature or source of heat not completely covered behind a solid object, such as a wall; this bypasses any concealment granted by smoke or darkness. It can similarly detect especially cold creatures and sources of cold. Almost all creatures with the cold or fire trait can be detected with heatvision. Undead and constructs are typically the same temperature as their environment and can't be detected with heatvision. The GM decides in other cases.\n\nHeightened (6th) The duration lasts until you next make your daily preparations, and the range increases to 120 feet.","source":{"provider":"PAIZO","sourceId":"73gohsek77nLGPWC","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hedge-prison","name":"Hedge Prison","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 Medium or smaller creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You conjure an intricate hedge prison to trap a creature, encasing them completely in a hollow cube of dense bushes. The hedge has AC 5, Hardness 5, and 20 Hit Points. It's immune to critical hits and precision damage.\n\nCritical Success The creature escapes the hedge before it fully forms.\n\nSuccess The creature is trapped inside the hedge, but the hedge's Hit Points are reduced by half.\n\nFailure The creature is trapped inside the hedge.\n\nCritical Failure The creature is trapped inside the hedge, and the hedge's Hit Points are increased by half.\n\nHeightened (4th) The hedge's hardness increases to 7 and its Hit Points increase to 30.\n\nHeightened (5th) The hedge's hardness increases to 9 and its Hit Points increase to 40. You can target a creature of Large size or smaller.\n\nHeightened (6th) The hedge's hardness increases to 11 and its Hit Points increase to 50. You can target a creature of Large size or smaller.\n\nHeightened (7th) The hedge's hardness increases to 13 and its Hit Points increase to 60. You can target a creature of Huge size or smaller.\n\nHeightened (8th) The hedge's hardness increases to 15 and its Hit Points increase to 70. You can target a creature of Huge size or smaller.\n\nHeightened (9th) The hedge's hardness increases to 17 and its Hit Points increase to 80. You can target a creature of Huge size or smaller.","source":{"provider":"PAIZO","sourceId":"z0ffligcrkVtKZd6","book":"Pathfinder #202: Severed at the Root","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heroism","name":"Heroism","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You unlock the target's inner heroism, granting it a +1 status bonus to attack rolls, Perception checks, saving throws, and skill checks.\n\nHeightened (6th) The status bonus increases to +2.\n\nHeightened (9th) The status bonus increases to +3.","source":{"provider":"PAIZO","sourceId":"KqvqNAfGIE5a9wSv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.holy-light","name":"Holy Light","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["attack","concentrate","fire","holy","light","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"5d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":true,"ritual":null,"description":"You shine a blazing ray of light tinged with holy energy. Make a ranged spell attack. The ray deals 5d6 fire damage. If the target has the unholy trait, you deal an extra 5d6 spirit damage.\nCritical Success The target takes double damage.\n\nSuccess The target takes full damage.\n\nIf the light passes through an area of magical darkness or targets a creature affected by magical darkness, holy light attempts to counteract the darkness. If you need to determine whether the light passes through an area of darkness, draw a line between yourself and the spell's target.\nHeightened (+1) The fire damage increases by 2d6, and the spirit damage against unholy creatures increases by 2d6.","source":{"provider":"PAIZO","sourceId":"DyiD239dNS7RIxZE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.horde-of-underlings","name":"Horde of Underlings","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"I4N3zTQhgn4hsQXi","formula":"1d4","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon six underlings, such as skeletons or kobolds. When you cast this spell, you decide what kind of creatures they are, if they're Small or Medium, and whether they deal bludgeoning, piercing, or slashing damage (choose once and applying it to all underlings). Each underling has 1 Hit Point, 5 AC, and automatically fails all saving throws. Each underling appears in an unoccupied square of your choice within the area. The underlings don't block movement, but they are difficult terrain for creatures other than you.\n\nEach underling attacks one enemy adjacent to it (if any), automatically dealing 1d4 damage of the chosen type. The first time you Sustain the spell on each subsequent round, each underling moves 20 feet toward the nearest enemy. If an underling ends its movement adjacent to an enemy, it damages that enemy as described above.\nHeightened (+1) The number of underlings increases by 2","source":{"provider":"PAIZO","sourceId":"y5amezSt82FYu9HG","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.horrific-visage","name":"Horrific Visage","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","emotion","fear","focus","illusion","manipulate","mental","sorcerer","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You briefly transform your features into the horrific visage of a hag, striking fear into your enemies. Foes in the area must attempt a Will save.\n\nSuccess The foe is unaffected.\n\nFailure The foe is Frightened 1.\n\nCritical Failure The foe is Frightened 2.\n\nHeightened (5th) Foes in the area are Frightened 1 on a success, Frightened 2 on a failure, and Frightened 3 and for 1 round on a critical failure. They are still unaffected on a critical success.","source":{"provider":"PAIZO","sourceId":"aZg3amDcrXz3cLCz","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hypercognition","name":"Hypercognition","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You rapidly catalog and collate information relevant to your current situation. You can instantly use up to 6 Recall Knowledge actions as part of Casting this Spell. For these actions, you can't use any special abilities, reactions, or free actions that trigger when you Recall Knowledge.","source":{"provider":"PAIZO","sourceId":"ZYoC630tNGutgbE0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hypnotize","name":"Hypnotize","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["illusion","manipulate","subtle","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a cloud of mesmerizing patterns and colors that hovers in the air. Creatures are while inside the cloud. In addition, a creature must attempt a Will saving throw if it is inside the cloud when you cast it, when it enters the cloud, when it ends its turn within the cloud, or if it uses a or Interact action on the cloud. A creature currently by hypnotize doesn't attempt new saves.\n\nSuccess The target is unaffected.\n\nFailure The target is fascinated by the cloud.\n\nCritical Failure The target is fascinated by the cloud. While it remains fascinated, it can't use reactions.","source":{"provider":"PAIZO","sourceId":"K2WpC3FFoHrqX9Q5","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ibexs-harvest","name":"Ibex's Harvest","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 or more creature","area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"9lBbiFhEGXB6Gu6a","formula":"2d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"9lBbiFhEGXB6Gu6a":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"In the tale \"Ibex's Harvest,\" Ibex turns from the path of a warrior to the path of a farmer, building up their community by working hard and sharing a bountiful harvest not just with their humanoid neighbors but also with their animal neighbors. Ibex initially focuses on distributing equally among the animals but learns that true equality requires knowing what each being needs. The number of actions you spend when Casting this Spell and telling the story determine its targets and effects.\n\n1 You give a brief description of Ibex's first bounty. One willing target you can touch gains 10 temporary Hit Points that last 1 minute.\n\n2 You tell the tale of how Ibex shared their harvest equally between Hippo and Ant. Two willing targets within 20 feet each gain 10 temporary Hit Points that last 1 minute.\n\n3 You impart Ibex's lesson about how to prevent others from taking advantage of generosity. All creatures within a 10-foot emanation are affected by the tale. Choose one creature in the emanation to take 2d8 mental (basic Will save), while each other creature in the emanation gains 5 temporary Hit Points that last 1 minute.\nHeightened (+1) The temporary Hit Points increase by 3 and the mental damage for the 3-action version increases by 1d8.","source":{"provider":"PAIZO","sourceId":"P7AToTm0ulueRk63","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.impending-doom","name":"Impending Doom","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","emotion","fear","incapacitation","manipulate","mental","prediction"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"3 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"6d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You sift through myriad potential futures, seize upon one potential moment in which the target meets a particularly gruesome and fatal end, and then show it a vision of its impending demise. The intense mental vision grows more and more terrifying to the target as the doom grows closer, and it takes 3 rounds to reach its conclusion. The target must attempt a Will saving throw to determine the effects. At the end of the spell's duration, if the target was affected, the target witnesses its death and takes 6d6 mental damage.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is unaffected for 1 round. On the second round, it becomes . Finally, on the third round, it becomes Frightened 1. At the end of the third round, it takes half damage.\n\nFailure The creature is immediately off-guard. On the second round, it becomes Frightened 2. Finally, on the third round, it also becomes Stunned 1. At the end of the third round, the creature takes full damage.\n\nCritical Failure The creature is immediately off-guard and Frightened 3. On the second round, it becomes stunned 1. Finally, on the third round, it also becomes . At the end of the third round, the creature takes double damage.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"rfFZKfeCSweFv7P3","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.incendiary-ashes","name":"Incendiary Ashes","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"65f6xZwo4IJ1ziZn","formula":"4d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"65f6xZwo4IJ1ziZn":"2d6"}},"counteraction":false,"ritual":null,"description":"A cloud of magical ashes descends upon creatures in the area. The ashes scour flesh and linger in the wounds, igniting upon the slightest flicker of flame. Creatures in the area take 4d6 slashing damage and must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and has weakness to fire 3 until the start of its next turn.\n\nFailure The creature takes full damage and has weakness to fire 3 for 1 minute. If the creature is killed by fire during this time it's reduced to ashes, though its gear remains.\n\nCritical Failure As failure, except the creature takes double damage.\n\nHeightened (+1) The slashing damage increases by 2d6 and weakness to fire increases by 1.","source":{"provider":"PAIZO","sourceId":"OTd17oXwJH9qb1cS","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.infectious-ennui","name":"Infectious Ennui","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","emotion","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a wave of your hand and a short invocation, you cause feelings of ennui and impending doom to well up in the mind of the targeted creature, who must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is momentarily overwhelmed with ennui. It becomes Slowed 1 as it grapples mentally with the pointlessness of existence, but at the end of the target's next turn, the spell effect ends.\n\nFailure The target is slowed 1 and Frightened 1 from the sense of ennui, and remains slowed and can't reduce the frightened condition below 1 as long as the spell is sustained. At the start of the target's turn, choose one creature within 30 feet of the target to attempt a Will save as well; on a failure, that creature is slowed 1 for 1 round; either way, they are then temporarily immune to this casting of infectious ennui. (Ennui does not continue to spread from this secondary target.)\n\nCritical Failure As failure, but the primary target is Slowed 2 and Frightened 2.\n\nHeightened (5th) When a secondary target becomes slowed, it remains slowed as long as the spell is sustained.","source":{"provider":"PAIZO","sourceId":"oYBIs8MICYkFwtXD","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.inscrutable-mask","name":"Inscrutable Mask","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","illusion","manipulate","shadow"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud your form and features in an impenetrable mask of shadow. The mask grants you a +1 status bonus to Deception checks to or , Intimidation checks to , and Stealth checks to in areas of dim light or darkness.\n\nHeightened (6th) The status bonus increases to +2.\n\nHeightened (9th) The status bonus increases to +3.","source":{"provider":"PAIZO","sourceId":"YQWq1DZuLRk32M3h","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.insect-form","name":"Insect Form","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL","ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You envision a simple bug and transform into a Medium animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as a ladybug or scarab for beetle), but this has no effect on the form's Size or statistics. While in this form, you gain the animal trait. You can Dismiss this spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 18 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 10 temporary Hit Points.\n\n- Low-light vision.\n\n- One or more attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +13, and your damage bonus is +2. These attacks are Strength based (for the purpose of the condition). If your unarmed attack modifier is higher, you can use it instead.\n\n- Athletics modifier of +13, unless your own is higher.\n\nYou also gain specific abilities based on the form you choose:\n- Ant\n- Speed 30 feet, climb Speed 30 feet;\n\n- Melee 1 mandibles, Damage 2d6 bludgeoning.\n\n- Beetle\n- Speed 25 feet;\n\n- Melee 1 mandibles, Damage 2d10 bludgeoning.\n\n- Centipede\n- Speed 25 feet, climb Speed 25 feet; darkvision;\n\n- Melee 1 mandibles, Damage 1d8 piercing plus 1d4 persistent poison.\n\n- Mantis\n- Speed 40 feet; imprecise scent 30 feet;\n\n- Melee 1 foreleg, Damage 2d8 piercing.\n\n- Scorpion\n- Speed 40 feet; darkvision, imprecise tremorsense 60 feet;\n\n- Melee 1 stinger, Damage 1d8 piercing plus 1d4 persistent poison;\n\n- Melee 1 pincer (agile), Damage 1d6 bludgeoning.\n\n- Spider\n- Speed 25 feet, climb Speed 25 feet; darkvision;\n\n- Melee 1 fangs, Damage 1d6 piercing plus 1d4 persistent poison;\n\n- Ranged 1 web (range increment 20 feet), Damage Immobilizes the target for 1 round or until it [[/act escape]]{Escapes}.\n\nHeightened (4th) Your battle form is Large, and your attacks have 10-foot reach. You instead gain 15 temporary HP, attack modifier +16, damage bonus +6, and Athletics +16.\n\nHeightened (5th) Your battle form is Huge, and your attacks have 15-foot reach. You instead gain 20 temporary HP, attack modifier +18, damage bonus +2 and double damage dice (including persistent damage), and Athletics +20.","source":{"provider":"PAIZO","sourceId":"XI6Lzd2B5pernkPd","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.instant-parade","name":"Instant Parade","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["auditory","aura","concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"An illusory parade with dozens of participants and performers appears around you, following you as you move. The parade is lively and noisy, providing enough cover and distraction to hide among the crowd. You and other creatures can and inside the crowd, though creatures that disbelieve the illusion still see creatures within as normal.\n\nYou can choose to send the parade off with a 2-action activity, which has the concentrate trait. When you do so, the parade no longer follows you and instead continues traveling in the direction of your choice. The parade travels 100 feet over 1 round and then disappears as the spell is Dismissed. You can otherwise Dismiss the spell normally if you prefer.","source":{"provider":"PAIZO","sourceId":"xyRjD52YZl3DBsiy","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.interstellar-void","name":"Interstellar Void","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cold","concentrate","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"3d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You call upon the frigid depths of outer space to bring a terrible chill to your enemy. The target is cloaked in the freezing void, which deals 3d6 cold damage immediately and the first time each round you Sustain the Spell on future turns, with a basic Fortitude save.\n\nThe target is for as long as the effect persists.\n\nHeightened (+1) The cold damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"L37RTc7K79OUpZ7X","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.invoke-the-harrow","name":"Invoke the Harrow","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw a card from the harrow, either one from a deck you have in hand or magically produce one as part of the spell. You use the power of the card's suit to influence a creature around you. When you draw a card, you can choose to impart a boon or bane associated with the card's suit. The target must attempt a Will save. On a failure, they receive the effects of the chosen boon or bane. If you target an ally with this spell, they can choose to willingly accept the effects without attempting a saving throw. The target can attempt to remove the card's influence by using an action, which has the concentrate trait, to attempt the saving throw again; on a success, the effect ends.\n\nTo determine the card, draw a card from a harrow deck. If you don't have a harrow deck available, you can roll 1d6 to randomly determine the suit you draw.\n\n1. Hammers (Str) Boon: The target gains a +2 status bonus to damage rolls; Bane: The target is Enfeebled 1.\n\n2. Keys (Dex) Boon: The target gains a +1 status bonus to AC; Bane: The target is Clumsy 1.\n\n3. Shields (Con) Boon: The target gains temporary Hit Points equal to twice the spell's rank; Bane: The target is Drained 1.\n\n4. Books (Int) Boon: The target gains a +1 status bonus to skill checks; Bane: The target is Stupefied 1.\n\n5. Stars (Wis) Boon: The target gains a +1 status bonus to saving throws; Bane: The target is .\n\n6. Crowns (Cha) Boon: The target can roll twice and take the higher result on a single check during the duration. This is a fortune effect; Bane: The target must roll twice and take the lower result on a single check of your choosing during the duration. This is a misfortune effect.\n\nHeightened (6th) The duration is 1 minute. The target must succeed a total of two saving throws to end the effect. The value of boons and banes doubles. The Crowns suit affects a total of three checks during the duration.","source":{"provider":"PAIZO","sourceId":"82gDiXTKsCmdIF6Q","book":"Pathfinder Stolen Fate Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ki-cutting-sight","name":"Ki Cutting Sight","kind":"SPELL","rank":3,"rarity":"RARE","traits":["focus","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Ki flows through everything in existence—animals and plants, living and dead, mortals and spirits. Strike at just the right place, in just the right way, and the flow is stopped, with dire consequences.\n\nWhen you Cast the Spell, make a perception check against the target's Fortitude DC. If you succeed, the next time you deal damage to the target with a Strike or ki spell, you deal 4d10 additional slashing damage.\n\nHeightened (+1) The slashing damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"jrlCEw9rqBi4qU6g","book":"Pathfinder Wake the Dead #2","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.labyrinthine-prison","name":"Labyrinthine Prison","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["mythic","teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"fine paper and ink worth a total value of the target's level × 25 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature of up to 8th level","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Deception (expert), Maze Lore (trained), or Religion (expert)","secondaryChecks":"Art Lore (trained), Crafting (trained), or Thievery (trained)","secondaryCasters":2},"description":"This ritual was developed by a long-dead minotaur hero-god whose cult trained to hunt and trap evil beings. It creates a maze of ever-shifting warped space woven from intertwined demiplanes that twist in ways few can solve.\n\nYou and the secondary casters draw a maze of twisted space into being with the target at its center. An unwilling target must be , , or otherwise prevented from leaving the area for the entire casting time, or the ritual fails. An unwilling target can attempt a Will save to resist the ritual; on a critical success, treat the result as critically failing to cast the ritual. While the target is trapped within the labyrinthine prison, they cannot escape it, as even abilities that give access to other planes are subject to being twisted into the maze. Instead the only way to escape is by succeeding at a Maze Lore, Perception, or Survival check against the labyrinthine prison's DC. This check can be attempted once per week, and the first check can only be attempted after a week has passed. If all casters spend one Mythic Point each, this interval changes to one year, and the DC uses the primary caster's mythic proficiency.\nCritical Success As success, and the twisted space renders the target Stupefied 2 while within.\n\nSuccess The target is trapped within the labyrinthine prison for the duration of ritual.\n\nFailure The ritual fails to trap the target.\n\nCritical Failure As failure, and the casters are all Stupefied 4 for 1 week.\nHeightened (4th) The maximum level of the target is 10. The cost is the target's level (minimum 1) × 40 gp. The interval becomes 1 month, and spending Mythic Points increases it to 5 years.\n\nHeightened (5th) The maximum level of the target is 12. The cost is the target's level (minimum 1) × 75 gp. The interval becomes 2 months, and spending Mythic Points increases it to 10 years.\n\nHeightened (6th) The maximum level of the target is 14. The cost is the target's level (minimum 1) × 125 gp. The interval becomes 6 months, and spending Mythic Points increases it to 30 years.\n\nHeightened (7th) The maximum level of the target is 16. The cost is the target's level (minimum 1) × 200 gp. The interval becomes 1 year, and spending Mythic Points increases it to 50 years.\n\nHeightened (8th) The maximum level of the target is 18. The cost is the target's level (minimum 1) × 300 gp. The interval becomes 2 years, and spending Mythic Points increases it to 100 years.\n\nHeightened (9th) The maximum level of the target is 20. The cost is the target's level (minimum 1) × 600 gp. The interval becomes 5 years, and spending Mythic Points increases it to 200 years.","source":{"provider":"PAIZO","sourceId":"WRRbNyGam4ytTRgr","book":"Pathfinder #217: Death Sails a Wine-Dark Sea","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lashing-rope","name":"Lashing Rope","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["attack","concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":50},"target":"up to 50 feet of unattended rope or an inanimate rope-like object","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"ptca9SPN1Z5wzfrG","formula":"3d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"ptca9SPN1Z5wzfrG":"2d6"}},"counteraction":false,"ritual":null,"description":"You cause a section of rope or a rope-like object to animate, slither to your square, and encircle you, wreathing you in twisting, lashing fibers.\n\nWhen you Cast the Spell and each time you Sustain the Spell, you can make a melee Strike with the rope, which uses and contributes to your multiple attack penalty. These rope Strikes are melee spell attacks; have the magical, reach, and trip weapon traits; and deal 3d6 slashing damage.\n\nIf you critically fail a check to using the rope, you can't make any more Strikes with it this turn, nor can you use it to make an Attack of Opportunity until the beginning of your next turn. This replaces the usual results of a critical failure to Trip.\n\nHeightened (+2) The damage from your rope Strikes increases by 2d6.","source":{"provider":"PAIZO","sourceId":"sbTxe4CGP4tn6y51","book":"Pathfinder Adventure Path: Gatewalkers","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.levitate","name":"Levitate","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 unattended object or willing creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You defy gravity and levitate the target 5 feet off the ground. You can Sustain the spell to move the target up or down 10 feet. A creature floating in the air from levitate takes a –2 circumstance penalty to attack rolls. A floating creature can spend an Interact action to stabilize itself and negate this penalty for the remainder of its turn. If the target is adjacent to a fixed object or terrain of suitable stability, it can move across the surface by climbing (if the surface is vertical, like a wall) or crawling (if the surface is horizontal, such as a ceiling). The GM determines which surfaces can be climbed or crawled across.","source":{"provider":"PAIZO","sourceId":"fI20AVwOzJMHXRdo","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-connection","name":"Life Connection","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","contingency","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When you cast this spell, you place a failsafe deep within the life force of the target. You can sense when the target takes damage, provided you're within 1 mile of one another. A creature can be part of no more than one life connection simultaneously. When the spell is complete, you gain the reaction; once you use the reaction, the spell ends.","source":{"provider":"PAIZO","sourceId":"HIY4XUJZKmFLAJTn","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-pact","name":"Life Pact","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"up to 6 willing creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"Using your life force or spirit as a conduit, you bind the targets in a mystical pact. If one of the targets is about to take damage that would reduce it to 0 Hit Points, all other targets immediately lose 3 Hit Points and the triggering target regains a number of Hit Points equal to the Hit Points lost this way, just before taking the damage. If this healing is enough that the triggering target is no longer reduced to 0 Hit Points, they remain conscious. Once the triggering target has regained Hit Points from the other targets, the spell ends.\n\nHeightened (+1) Increase the number of Hit Points lost by 1 for each target other than the one reduced to 0 Hit Points. The target reduced to 0 Hit Points regains that many additional Hit Points.","source":{"provider":"PAIZO","sourceId":"vvbS69EHZuUTq0dr","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lightning-bolt","name":"Lightning Bolt","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","electricity","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":120}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"A bolt of lightning strikes outward from your hand, dealing 4d12 electricity damage.\n\nHeightened (+1) The damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"9AAkVUCwF6WVNNY2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.locate","name":"Locate","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 specific object or type of object","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You learn the direction to the target (if you picked a specific object, such as \"my mother's sword\") or the nearest target (if you picked a type of object, such as \"swords\"). If the target is a specific object, you must have observed it directly with your own senses. If it's a type of object, you still need to have an accurate mental image of the type of object. If there's lead or running water between you and the target, this spell can't locate the object. This means you might find a type of object farther away if the nearest one is behind lead or running water.\n\nHeightened (5th) You can target a specific creature or ancestry instead of an object, but you must have met or seen up close the creature or ancestry you want to target.","source":{"provider":"PAIZO","sourceId":"LQzlKbYjZSMFQawP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lotus-walk","name":"Lotus Walk","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Lotuses, water lilies, and other watery plants bloom at your feet, allowing you to walk on the surface of water and other liquids. You can go underwater if you wish, but in that case, you must Swim normally. As you Stride or Step on water, you leave a trail of oversized lily pads, lotus leaves, or spatterdock that fill the squares' surfaces in your wake. Each square of this trail can withstand the weight of 1 Medium creature and lasts until the end of your next turn. You can Dismiss this spell early.\n\nHeightened (4th) The duration of this spell increases to 10 minutes. The trail lasts until the spell ends or you Dismiss the spell on you, whichever comes first.\n\nHeightened (6th) The duration increases to 1 hour. Your trail is permanent even if you Dismiss the spell on you, although if the water can't support such plants, they'll die in a week. The trail can be removed by dispel magic or a similar spell.","source":{"provider":"PAIZO","sourceId":"OuZY7VYeylub5K7l","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mad-monkeys","name":"Mad Monkeys","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Magical monkey spirits fill the area as they pile and climb on top of one another. Because the monkeys are magical spirits, they can't be attacked or hurt. Casting or a similar effect over the monkeys makes them docile, causing them to cease making mischief for the duration of mad monkeys.\n\nChoose the kind of mischief your monkeys make when you Cast the Spell. They produce the effect listed for that mischief when you Cast the Spell and the first time each round when you Sustain the Spell. The first time each round when you Sustain the Spell, you can move the area of the monkeys by 5 feet.\n\nFlagrant Burglary The monkeys try to any one item from one creature in the area. Use your spell DC - 10 as the monkeys' Thievery modifier. Their attempt relies more on distraction than subtlety, so the victim knows what item the monkeys were trying to take and whether it was taken. Getting a stolen item from the monkeys-even for the caster-requires Stealing it from them or Disarming them, using your spell DC. When the spell ends, any stolen items fall to the ground in any square of the spell's area you choose.\n\nRaucous Din The monkeys screech loudly, potentially deafening creatures in the spell's area. Each creature in the spell's area must attempt a Fortitude save.\n\nCritical Success The creature is unaffected and is temporarily immune for 10 minutes.\n\nSuccess The creature is unaffected.\n\nFailure The creature is for 1 round.\n\nCritical Failure The creature is Deafened for 1 minute.\n\nTumultuous Gymnastics The monkeys jump and climb all over creatures in the spell's area, interfering with complex movements. Each creature in the spell's area must attempt a Reflex save.\n\nCritical Success The creature is unaffected and is temporarily immune for 10 minutes.\n\nSuccess The creature is unaffected.\n\nFailure For 1 round, the creature must succeed at a flat whenever it attempts a manipulate action. If it fails this check, the creature loses that action.\n\nCritical Failure As failure, but the monkeys cling to the creature tenaciously, and the effect lasts until the spell ends, even if the creature leaves the spell's area.","source":{"provider":"PAIZO","sourceId":"tFKJCPvOQZxKq6ON","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magical-fetters","name":"Magical Fetters","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Ghostly manacles launch from your outstretched hand and clasp around the target's limbs, impeding its movements. The target must attempt a Reflex save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Clumsy 1 and takes a –10-foot status penalty to its Speed for 1 round.\n\nFailure The target is clumsy 3 and takes a –10-foot status penalty to its Speed for 1 minute.\n\nCritical Failure As failure, but the target is also Slowed 1 for the duration.","source":{"provider":"PAIZO","sourceId":"2ZPqcM9wNoVnpwkK","book":"Pathfinder #158: Sixty Feet Under","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magnetic-acceleration","name":"Magnetic Acceleration","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["attack","concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature or object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1d6"}},"counteraction":false,"ritual":null,"description":"You magnetize a small metal object, such as a nail or coin, and launch it away from you at massive speed. Make a ranged spell attack roll; if the target is wearing metal armor or is made of metal, you gain a +1 circumstance bonus to your attack roll with magnetic acceleration. On a hit, the target takes 3d6 bludgeoning damage and 3d6 piercing damage, or double damage on a critical hit.\n\nHeightened (+1) The bludgeoning and piercing damage each increase by 1d6.","source":{"provider":"PAIZO","sourceId":"Tx8OqkBFA2QlaldW","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.malicious-shadow","name":"Malicious Shadow","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","hex","manipulate","shadow","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d10","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d10"}},"counteraction":true,"ritual":null,"description":"Your patron warps the target's shadow into a deadly form, such as strangling hands, a dangerous weapon, harrying runes, or the like. The shadow moves along with the target, always remaining within reach. When you Cast the Spell, and each time you Sustain it, the shadow Strikes the target. The shadow's Strikes are melee spell attacks that deal 2d10 damage. You choose the type of damage (bludgeoning, piercing, or slashing) when you Cast the Spell. The shadow uses and contributes to your multiple attack penalty. The shadow doesn't take up space, grant flanking, or have any other attributes a creature would. The shadow can't make any attacks other than its Strike.\n\nThe shadow vanishes if the target ceases to cast a shadow (usually if it moves into complete darkness or light). If another effect is controlling the target's shadow when you cast malicious shadow, you can attempt to counteract that effect to temporarily take control of the shadow for malicious shadow's duration.\nHeightened (+2) The Strike damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"vhMCd15ZwNJn0zen","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.martyrs-intervention","name":"Martyr's Intervention","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","healing"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range would take damage that reduces it to 0 Hit Points\n\nRequirements You don't have the wounded condition.\n\nYou shield a creature in dire need with your own life force, taking the harm upon yourself to save their life. The target is reduced to 1 Hit Point instead of 0 Hit Points. All remaining damage that was prevented from harming the target creature is instead dealt to you. Both you and the target become Wounded 1; targets who are already wounded increased their wounded value by 1.","source":{"provider":"PAIZO","sourceId":"M9TiCE1vlG1j2faM","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mind-of-menace","name":"Mind of Menace","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","contingency","emotion","fear","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This spell wards against those who attempt to subvert your mind and turns mental magic back on them. When the spell is complete, you gain the reaction; once you use the reaction, the spell ends.","source":{"provider":"PAIZO","sourceId":"fPlFRu4dp09qJs3K","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mind-reading","name":"Mind Reading","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round or sustained up to 1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a cursory mental touch, you attempt to read the target's mind. It must attempt a Will save. The target then becomes temporarily immune to your mind reading for 1 hour.\n\nCritical Success The target perceives vague surface thoughts from you when you Cast the Spell.\n\nSuccess You find out whether the target's Intelligence modifier is higher than, equal to, or lower than yours.\n\nFailure You perceive vague surface thoughts from the target when you Cast the Spell, and you find out whether its Intelligence is higher than, equal to, or lower than yours.\n\nCritical Failure As failure, and for the duration of the spell, you can Sustain the spell to detect the target's surface thoughts again. The target doesn't receive any additional saves.","source":{"provider":"PAIZO","sourceId":"KHnhPHL4x1AQHfbC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mindscape-door","name":"Mindscape Door","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":["illusion"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"incense and focusing diagrams worth a total value of the target's level (minimum 1) × 1 gp, for each target"},"targeting":{"range":{"kind":"TOUCH"},"target":"yourself and up to 5 willing creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Arcana or Occultism, Deception or Diplomacy, Perception","secondaryCasters":3},"description":"You project the targets into an immersive mindscape or cause them to exit one. You must be aware the mindscape exists, though you don't need to know specifics. The casters must be in physical contact with one another in a circle for the duration of the casting and all targets must be selected from these casters. Your bodies typically remain behind in stasis when you enter a mindscape, though some mindscapes pull you entirely into them upon entrance. If you enter a mindscape, you can leave only by using another mindscape door ritual, finding an exit within the nature of the mindscape, or when the mindscape ceases to exist. When exiting a mindscape, you typically return to your bodies or to the location where you entered the mindscape. If the mindscape's creator wants to prevent anyone from entering or exiting, the DC of the primary check is the creator's Will DC if that would be higher than the ritual's normal DC.\nCritical Success You transport the creatures as you intended and can leave a portal that lasts for an unlimited duration. It typically looks like an ordinary door or passage appropriate to the mindscape. Any target of the spell can enter or exit through this portal as they would an ordinary door. If you wish, you can make the door passable by anyone.\n\nSuccess You transport the creatures as you intended.\n\nFailure You fail to enter or exit the mindscape.\n\nCritical Failure Something goes horribly wrong. The GM decides whether mental feedback deals 9d6[mental] damage to all ritual casters (will) or 1d4 casters are unwillingly pulled into the mindscape (or ejected from it).\nHeightened (8th) The ritual targets up to 100 willing creatures, the critical failure damage increases to 20d6, and the critical failure save DC increases to 40.","source":{"provider":"PAIZO","sourceId":"8MAHUK6jphbME4BR","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mindscape-shift","name":"Mindscape Shift","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"focusing diagrams and incense worth 28 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"yourself and the secondary casters","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert) or Willowshore Lore","secondaryChecks":"Arcana, Deception, Diplomacy, Occultism, Perception, or Willowshore Lore","secondaryCasters":3},"description":"","source":{"provider":"PAIZO","sourceId":"VJgSQBYwXGDbMmiW","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.moonlight-ray","name":"Moonlight Ray","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["attack","cold","concentrate","holy","light","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"z4vh7m14o6f2hazs","formula":"5d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"z4vh7m14o6f2hazs":"2d6"}},"counteraction":false,"ritual":null,"description":"You unleash a holy beam of freezing moonlight. Make a ranged spell attack. The ray deals 5d6 cold damage; if the target has the unholy trait, you deal an extra 5d6 spirit damage.\n\nMoonlight ray's cold damage is silver damage for the purposes of weaknesses, resistances, and the like.\nCritical Success The target takes double cold damage, as well as double spirit damage if a fiend or undead.\n\nSuccess The target takes full damage.\n\nIf the light passes through an area of magical darkness or targets a creature affected by magical darkness, moonlight ray attempts to counteract the darkness. If you need to determine whether the light passes through an area of darkness, draw a line between yourself and the spell's target.\nHeightened (+1) The cold damage increases by 2d6, and the spirit damage against fiends and undead increases by 2d6.","source":{"provider":"PAIZO","sourceId":"mtlyAyf30JnIvxVn","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.moths-supper","name":"Moth's Supper","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"xiuuffbu1j9b54eq","formula":"2d4","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"xiuuffbu1j9b54eq":"1d4"}},"counteraction":false,"ritual":null,"description":"You sigh, and your breath transforms into delicate, black-winged butterflies and huge death's-head hawkmoths. They flutter about you briefly, and then range forth in search of sustenance—fresh-spilled blood, by preference, but rotting corpses, flowering plants, or even left-behind food will do in a pinch. They then return, perching on your hair or shoulders and whispering their secrets into your ears. This has three effects.\n- You heal 2d4 Hit Points every 10 minutes.\n- The first time during the duration when someone successfully Treats your Wounds, you regain an additional 4d4 Hit Points.\n- You gain an imprecise sense out to 30 feet that senses only freshly spilled blood and rotten flesh.\nHeightened (+1) The amount of Hit Points healed every 10 minutes increases by 1d4 and the amount of Hit Points regained from the first increases by 2d4.","source":{"provider":"PAIZO","sourceId":"xabHqik5SoyDc5Db","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mycological-malady","name":"Mycological Malady","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","disease","focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infect your target with fungal spores to hasten the cycle of decay. The target must attempt a Fortitude saving throw. Undead that aren't incorporeal, such as skeletons and zombies, don't have their normal immunity to this disease, as the spores can still colonize their remaining flesh and bone. This might also apply to other non-living creatures made of organic material at the GM's discretion.\n\nCritical Success The target is unaffected.\n\nSuccess The target sprouts mushrooms and is Enfeebled 2 for 1 round.\n\nFailure The target is afflicted with voidcap spores at stage 1.\n\nCritical Failure The target is afflicted with voidcap spores at stage 2.\n\nVoidcap Spores (disease) This disease ends when the spell ends;\n\nStage 1 enfeebled 2 (1 round)\n\nStage 2 enfeebled 2 and Slowed 1 (1 round)\n\nStage 3 enfeebled 2, slowed 1, and Stupefied 2 (1 round)","source":{"provider":"PAIZO","sourceId":"V4jrHiaMh4XuANOP","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mystic-carriage","name":"Mystic Carriage","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"toy carriage, horse statues, rare incense, and feathers worth 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 week or until the named destination is reached, whichever comes first","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (Expert) or Occultism (Expert)","secondaryChecks":"Crafting or Driving Lore","secondaryCasters":0},"description":"This ritual allows you and the other casters to conjure a magical carriage that transports you to a destination of your choice. To summon the mystic carriage, you must be within 250 miles of your destination and spend 1 hour burning incense and feathers while chanting the name of the location you wish the carriage to take you to. When it arrives, the carriage is a Large vehicle that can fit 4 Medium or smaller passengers, as well as 100 Bulk. It has a Speed of 60 feet, AC of 14, Fortitude saving throw modifier of +8, Hardness 5, 100 Hit Points (BT 50), object immunities, and immunities to critical hits and precision damage.\n\nOnce loaded and boarded, the mystic carriage sets out at a Speed of 60 feet, heading unerringly towards its destination using whatever roads and trails are available. If it's attacked, it continues going as long as nothing blocks its passage. If something blocks its way, living or otherwise, it will stop until the way is cleared, waiting to continue until all of its passengers are aboard once more.\n\nCritical Success You create a mystic carriage that lasts for 2 weeks, instead of 1 week. It can take you to up to two destinations, the first of which must be within 250 miles and the second of which must be within 250 miles of the first destination.\n\nSuccess You create a mystic carriage as described above.\n\nFailure You don't create a mystic carriage.\n\nCritical Failure You don't create a mystic carriage, and you're attacked by a herd of four riding horses.\n\nHeightened (+1) The carriage's AC, Fortitude save, and Hardness increase by 2, its Hit Points increase by 20, and its Broken Threshold increases by 10.","source":{"provider":"PAIZO","sourceId":"jOWQ5wPd4xvSkjI5","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nothing-up-my-sleeve","name":"Nothing Up My Sleeve","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an extradimensional space within each of your sleeves. If you're not wearing clothing with sleeves, the spell also produces a simple shirt with long sleeves for you for the duration. Each of the extradimensional spaces can hold objects and equipment, up to a total of 1 Bulk. Organic matter and living creatures can't be stored in these spaces. You are the only person who can access or perceive these extradimensional spaces.\n\nYou can Interact to place an object into the extradimensional space or to draw an object from the extradimensional storage. When you draw an object from the extradimensional storage, the object appears in one of your empty hands. If you don't have an empty hand, you can't draw an object from the extradimensional storage. For the duration, whenever you , you can choose to place the palmed object directly into one of the two extradimensional spaces if that space has sufficient capacity to hold the object. When the spell ends or you die, the contents of both extradimensional spaces are ejected and land without harm on the ground in your space.","source":{"provider":"PAIZO","sourceId":"0aoRcxRyIPHfbifk","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.noxious-metals","name":"Noxious Metals","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","metal","poison"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"DzJpYMdE0NBqqQXM","formula":"4d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"DzJpYMdE0NBqqQXM":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"This spell forces toxic metal to coalesce on the skin or surface of all living creatures in the area, dealing 4d6 poison damage with a basic Fortitude save. Any creature that has the plant trait, has the wood trait, or has an anathema toward metal, takes the following effects depending on the result of that Fortitude save.\n\nCritical Success The creature suffers no additional effects.\n\nSuccess The creature takes 1[persistent,poison] damage and is Sickened 1 as long as it takes this persistent damage.\n\nFailure As success, except 1d4[persistent,poison] damage and Sickened 2.\n\nCritical Failure As success, except 1d8[persistent,poison] damage and Sickened 3.\n\nHeightened (+1) The initial poison damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"3A3ueS9Q0s3U8KXE","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.omnidirectional-scan","name":"Omnidirectional Scan","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","concentrate","psychic","scrying"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"target":"1 ally and 1 enemy","area":{"shape":"EMANATION","feet":30}},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You quickly view your surroundings from a variety of angles, your senses constructing an overall mental picture. You can choose to [[/act seek]] the entire emanation of the spell.\n\nRegardless of whether you seek, target one ally and one enemy in the area; if a target is or from you, you automatically succeed at the flat check to target it with this spell. You prepare to the target ally on an attack roll against the target enemy. If you take this Aid reaction, you use your spell attack modifier and proficiency rank on your check to Aid. If you critically fail the roll to Aid, you get a failure instead.","source":{"provider":"PAIZO","sourceId":"l4bHFR9UW2XiY3kH","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.one-with-stone","name":"One with Stone","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes or 8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can either transform into a stone or merge with stone. While transformed, you can't move or affect anything outside the stone, but you can cast spells as long as they don't require line of effect beyond the stone. You can Dismiss this spell.\n\n- Merge with Stone The spell's duration is 10 minutes. While casting the spell, you must touch a stone with enough volume to fit you and your possessions or the spell is disrupted. While merged, you can hear, but not see, what's going on outside the stone. If the stone takes damage while you're inside it, you're expelled from the stone and take 10d6 damage. Magic passage expels you without dealing damage. The spell ends if you're ever outside the stone.\n\n- Turn into a Stone The spell's duration is 8 hours. You become a Large stone. Perception checks don't reveal your true nature, but a successful Nature or Survival check against your spell DC reveals that you appear to be a stone that is strangely new to the area. While in this form, you can observe everything around you, using your normal senses. As a stone, your AC is 23, and only status bonuses, status penalties, circumstance bonuses, and circumstance penalties affect you. Any successes and critical successes you roll on Reflex saves are failures","source":{"provider":"PAIZO","sourceId":"vh1RpbWfqdNC4L3P","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.oneiric-mire","name":"Oneiric Mire","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental","visual"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud an area in illusory dreamstuff, making the ground look and feel like a deep mire or quicksand. Ground in the area is difficult terrain.\n\nEach creature in the area when the spell is cast, or that enters the area, must attempt a Will save. On a failure, it believes it's being pulled down by the earth, taking a –10-foot circumstance penalty to its Speeds. On a critical failure, it's also . In addition to the normal actions to Escape, at the end of an affected creature's turn, it can attempt a Will save, removing the effects on a success. On a critical success at any Will save made against oneiric mire, the creature fully disbelieves the illusion and no longer needs to make Will saves to risk a Speed penalty or being immobilized, though the area is still difficult terrain.","source":{"provider":"PAIZO","sourceId":"87zLUuTMmZ9zc7gH","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ooze-form","name":"Ooze Form","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You invoke all things that seep and ooze, your body dissolving into a thick slurry and then reconstituting itself into a Medium ooze battle form. When you first cast this spell, choose black pudding, gelatinous cube, gray ooze, or ochre jelly. While in this form, you gain the ooze trait. You can Dismiss the spell. You gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 7 + your level. Ignore your armor's check penalty and Speed reduction.\n- 20 temporary Hit Points.\n- You are immune to critical hits, precision damage, and visual effects.\n- Resistance 5 to acid, piercing, and slashing damage.\n- No vision and motion sense 30 feet. You can sense nearby motion through vibration and air movement as a precise sense.\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +14, and you use the listed damage. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n- Athletics modifier of +14, unless your own is higher.\nYou also gain specific abilities based on the ooze:\n- Black Pudding Speed 15 feet, climb 15 feet;\n- Melee 1 pseudopod, Damage 2d6+5 bludgeoning and 1d8 acid.\n\n- Gelatinous Cube Speed 15 feet;\n- Melee 1 cube face, Damage 1d6+5 acid;\n- a creature hit by your cube face Strike must succeed at a Fortitude save against your spell DC or be Stunned 1 (or for 1 round on a critical failure); this save has the incapacitation trait.\n\n- Gray Ooze Speed 15 feet, climb 15 feet, swim 15 feet\n- Melee 1 pseudopod, Damage 1d6+5 bludgeoning and 1d6 acid, and you can spend an action after a hit to the target.\n\n- Ochre Jelly Speed 15 feet, climb 10 feet; resistance 5 to electricity;\n- Melee 1 pseudopod, Damage 1d8+5 bludgeoning and 1d8 acid, and you can spend an action after a hit to the target.\n\nHeightened (4th) Your battle form is Large, and your attacks have 10-foot reach. You must have enough space to expand into or the spell is lost. You instead gain 30 temporary HP; resistance 7 to acid, piercing, and slashing; attack modifier +16; damage bonus +9; and Athletics +16. Your motion sense has a range of 40 feet.\n\nHeightened (5th) Your battle form is Huge, and your attacks have 15-foot reach. You must have enough space to expand into or the spell is lost. You instead gain 40 temporary HP; resistance 10 to acid, piercing, and slashing; attack modifier +18; damage bonus +6 and double damage dice; and Athletics +20. Your motion sense has a range of 60 feet.\n\nHeightened (8th) Your battle form is Gargantuan (20-foot- by-20-foot space), and your attacks have 20-foot reach. You must have enough space to expand into or the spell is lost. You instead gain 60 temporary HP; resistance 12 to acid, piercing, and slashing; attack modifier +28; damage bonus +13 and double damage dice; and Athletics +29. Your motion sense has a range of 60 feet.","source":{"provider":"PAIZO","sourceId":"0gdZrT9lwO17EIxc","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.organsight","name":"Organsight","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","revelation"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living or undead creature that has organs","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You see the target as though it's dissected and arrayed before you. For the duration, you gain a +2 circumstance bonus on Medicine checks against the target that depend on its organs, but a -2 circumstance penalty on Medicine checks depending on seeing its skin.\n\nWhen you Cast the Spell, attempt a special Recall Knowledge check using Medicine to spot and discern a vital organ. If you have a Lore skill appropriate to the creature, you can use that skill instead of Medicine. If you succeed, the next time you deal piercing or slashing damage to the target with a Strike or spell, you deal 4d6 additional precision damage. Once on each of your subsequent turns, you can use a single action to attempt the special Recall Knowledge check again. The extra damage isn't cumulative, so making the check more than once before a Strike or spell has no extra benefit.\n\nHeightened (+1) The precision damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"bH9cH9aDByY91l1d","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.overwhelming-memory","name":"Overwhelming Memory","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause the target to recall a specific type of memory you choose from the list below, bringing it to the forefront of their mind with perfect clarity.\n- Gleeful The memory makes the target laugh uncontrollably. They can't use reactions.\n- Romantic The creature is consumed with their love for another. They are by the memory.\n- Terrifying The creature is filled with terror and is Frightened 1.\n- Tragic The creature is overwhelmed with sorrow. They are from the tears in their eyes.\nThe target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target is affected by the memory until the beginning of your next turn.\n\nFailure The target is affected by the memory until the beginning of your next turn and Stupefied 2 for the spell's duration.\n\nCritical Failure As failure, but the target is Stupefied 3 for the spell's duration.","source":{"provider":"PAIZO","sourceId":"LJHrndGJRmLdxgXD","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.owb-pact","name":"Owb Pact","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryCasters":2},"description":"You call upon an owb to assist you in a goal. Only caligni callers can use this ritual with relative safety. If a different type of caligni attempts this ritual, they use an outcome one degree of success worse than the result of their check. If a non-caligni attempts this ritual, the result is an automatic critical failure.\n\nCritical Success You conjure the owb. It decides your goals closely match its own and doesn't request a favor in return.\n\nSuccess You conjure the owb. It isn't eager to pursue the task, so it requires a favor in return.\n\nFailure You don't conjure an owb.\n\nCritical Failure You conjure an owb, but it deems you unworthy and siphons away some of your soul energy. All casters become Doomed 2.","source":{"provider":"PAIZO","sourceId":"u3G7KX1qpFJlSeWm","book":"Pathfinder Monster Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.painted-scout","name":"Painted Scout","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","scrying"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"a cave wall or other stone surface","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You press your hand to the stone, causing hand-drawn scouts to spread out from your fingers. As long as you keep your hand on the wall and Sustain the Spell, you can see, hear, and smell through the painted scout using whatever senses you have (including natural senses like scent or darkvision, or magical effects like ). You can move the scout up to your Speed along the wall each time you Sustain the Spell. The scout can move anywhere along the wall to a range of 120 feet as long as its path is unbroken; it treats sharp corners and particularly craggy spots on the wall as difficult terrain. The painted scout is bonded to the wall on which you created it and can't move onto another surface or material.\n\nYou can spend an action to make the scout or , and you can roll a Nature or Occultism check in place of the usual Stealth check. The painted scout must be near a suitably obscured nook or cranny to Hide; it can't Hide or Sneak along a flat, featureless wall. If the painted scout is smeared or doused in water, the scout is destroyed and the spell ends.\n\nHeightened (6th) You create up to five separate painted scouts, and the range to which the scouts can move along the wall increases to 500 feet. Each time you Sustain the Spell, you can move one scout up to your Speed, and you can see, hear, and smell through all five scouts simultaneously. A destroyed scout can't be replaced, and the spell ends if all the scouts are destroyed.","source":{"provider":"PAIZO","sourceId":"oLylenH2jlP5UbRT","book":"Pathfinder #175: Broken Tusk Moon","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.paralyze","name":"Paralyze","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You block the target's motor impulses before they can leave its mind, threatening to freeze the target in place. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1.\n\nFailure The target is for 1 round.\n\nCritical Failure The target is Paralyzed for 4 rounds. At the end of each of its turns, it can attempt a new Will save to reduce the remaining duration by 1 round, or end it entirely on a critical success.\n\nHeightened (7th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"DCQHaLrYXMI37dvW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.perceive-the-threads-of-fate","name":"Perceive the Threads of Fate","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","fortune","mythic","prediction"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You open your mind to the grand design of existence, enabling you to view the threads of fate in all their complex, tangled glory. You attempt Perception checks and Reflex saving throws at mythic proficiency for the duration.\n\nYou can Sustain the spell once per round to untangle these threads. When you do, if your next action requires you to attempt an attack roll or skill check, you roll this check twice and use the higher result. You can untangle the threads of fate up to three times. After the third time, the spell ends.","source":{"provider":"PAIZO","sourceId":"QlivnxstGjlzaluf","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.percussive-impact","name":"Percussive Impact","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["attack","concentrate","manipulate","sonic"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"1kBezKdL9iXSMfzn","formula":"4d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"rcaspoacHgRYSM72","formula":"1d4","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"1kBezKdL9iXSMfzn":"4d8","rcaspoacHgRYSM72":"1d4"}},"counteraction":false,"ritual":null,"description":"You lob a compressed ball of sound at a foe. The ball explodes on impact, unleashing a powerful blast of sound. Make a spell attack roll. If you hit, you deal 4d8 bludgeoning damage plus 1d4 sonic splash damage. On a critical success, the target is also for 1 round.\nHeightened (+2) The bludgeoning damages increases by 4d8, the sonic splash damage increases by 1d4, and the duration of the deafened condition increases by 2 rounds.","source":{"provider":"PAIZO","sourceId":"iG1USiSRXMjCDGAr","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.perseiss-precautions","name":"Perseis's Precautions","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fortune","manipulate","prediction"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Leaving nothing to chance, you weave divinatory precautions against an ambush, alerting the target to danger. Once during the duration of this spell, the target can roll one Perception, Arcana, Crafting, Lore, Occultism, or Society initiative roll twice and take the better result, after which the spell ends.\n\nThe strain of staying so prepared is too much for a mind to handle for long; the target is temporarily immune to this spell for 24 hours once the spell ends, whether they used the initiative benefit or not.","source":{"provider":"PAIZO","sourceId":"ovx7O2FHvkjXhMcA","book":"Pathfinder Lost Omens Pathfinder Society Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.personal-blizzard","name":"Personal Blizzard","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cold","focus","hex","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"1d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1","1":"1"}},"counteraction":false,"ritual":null,"description":"Your patron's breath becomes blizzard of obscuring, scouring ice that follows your target. The target attempts a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 1d6[cold] damage, and the spell ends.\n\nFailure The target takes 1d6[cold] damage and 1d6[persistent,cold] damage. The persistent damage automatically ends when the spell ends. It is to other creatures, and other creatures are concealed to it.\n\nCritical Failure As failure, but both the cold damage and the persistent cold damage increase to 2d6.\n\nHeightened (+1) The cold damage and persistent cold damage increase by 1 (2 on a critical failure).","source":{"provider":"PAIZO","sourceId":"g4MAIQodRDVfNp1B","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.phantasmal-custodians","name":"Phantasmal Custodians","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare oils, salts, and herbs worth a total value of 15 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Arcana or Occultism (whichever isn't used for the primary check), Diplomacy","secondaryCasters":2},"description":"Area 100 feet × 100 feet, up to 20 feet high\nYou create a long-lasting adaptation of the , forming entities to carry out basic tasks at a fixed location.\nCritical Success The ritual creates six phantasmal minions. You don't need to concentrate on them, and they aren't summoned minions. You can spend an action, which has the concentrate trait, to command one to perform a basic task; it continues to perform the task until commanded again.\n\nSuccess As critical success, but the ritual creates three minions.\n\nFailure The ritual fails to create any phantasmal minions.\n\nCritical Failure The ritual creates six phantasmal minions, but these creatures are hostile and capable of making fist Strikes with an attack bonus equal to your skill modifier for the primary skill check, dealing 1d6 force damage. They attack you and your allies and attempt to break objects belonging to you and your allies within the area.\nHeightened (6th) If destroyed, the phantasmal minions reform the next morning. The cost increases to 30 gp","source":{"provider":"PAIZO","sourceId":"uuoPmbjEtqzWZs0v","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantom-prison","name":"Phantom Prison","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","illusion","incapacitation","manipulate","mental","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":50},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You completely surround a Large or smaller creature in immobile illusory walls, trapping it inside a false prison it can't escape. No other creatures see or feel these walls, and the target can't see anything outside of the illusory walls. The target can attempt a Will save when the spell is cast, each time it attempts to interact with or escape the walls, and each time something from outside the walls affects the target. On a success, it disbelieves the illusion and the spell ends.\n\nHeightened (8th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"Pwq6T7xpfAJXV5aj","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pillar-of-water","name":"Pillar of Water","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a large, self-contained cylinder of still, clear fresh water. You choose the radius and height of the pillar, to a maximum radius of 15 feet and a maximum height of 60 feet. Creatures inside the pillar can through the water as normal (athletics), or if the spell was cast on solid ground, walk along the bottom (which is difficult terrain). Any creature that exits the pillar falls or lands accordingly.","source":{"provider":"PAIZO","sourceId":"eIPIZp2FUbFcLNdj","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.positive-attunement","name":"Positive Attunement","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living or undead creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":3,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You attune a creature to the Forge of Creation, connecting its life force without fully transporting it. The creature's appearance becomes more brightly colored. If the creature is living, it heals 1d8 Hit Points immediately and at the end of each of your turns. Effects that increase healing only increase the initial healing.\n\nIf the creature is undead or has void healing, it instead takes 1d8 vitality damage, depending on the result of its Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is damaged once and the spell ends.\n\nFailure The creature is damaged immediately and at the end of each of your turns (so twice in the round you Cast the Spell).\n\nCritical Failure As failure, and the damage is doubled.\n\nHeightened (+3) The damage and healing each increase by 1d8.","source":{"provider":"PAIZO","sourceId":"9iJaD4S7ptUeq5vO","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.powerful-inhalation","name":"Powerful Inhalation","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["air","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You rapidly draw the air from your surroundings, hoarding it for yourself. Creatures in the area when the spell is cast take 5d6 bludgeoning damage with a basic Fortitude save. A creature that fails its save can't speak above a raspy whisper for 1 round. A creature that critically fails can't speak or use abilities that require it to breathe for 1 round. This prevents it from using effects that require speech, such as casting spells with verbal components, and from using a breath weapon or similar ability.\n\nCreatures made of air (such as air elementals) attempting a save against this spell get a degree of success one worse than they rolled.\n\nHeightened (+1) Increase the damage by 2d6.","source":{"provider":"PAIZO","sourceId":"v4QHuVOhFD1JMAqu","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.primal-chorus","name":"Primal Chorus","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["auditory","concentrate","manipulate","mental"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"1-mile burst"},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You let loose a primal howl that incites animals and beasts to join in the chorus. Doing so gives you a general idea of how many creatures with the animal or beast trait are within the range of the spell, but significant creatures can attempt a Will save against your spell DC to resist responding to your call. You gain a +1 status bonus to your next Initiative roll in an encounter with an enemy creature that replies to your call. For purposes of using during exploration mode, you can communicate with a creature that responds to your call for the duration of the spell. You can only make simple commands, such as approach or hide, and only understand simple ideas, such as compliance with the order or the presence of natural hazards.\n\nHeightened (+2) The status bonus increases by 1.","source":{"provider":"PAIZO","sourceId":"TPN3Z6VGau6Od9rG","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pulverizing-cascade","name":"Pulverizing Cascade","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You raise a pair of towering waves and slam them into each other, crushing creatures caught between them. Creatures in the area take 5d6 bludgeoning damage with a basic Reflex save.\n\nHeightened (+1) Increase the damage by 2d6.","source":{"provider":"PAIZO","sourceId":"E80SrXuBdZViPGiH","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.purging-toxins","name":"Purging Toxins","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","oracle","poison"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"GICIEVwjlpO0WPSv","formula":"@item.rank","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"In the right dose, a scourge can become a cure. Deal poison damage equal to the spell's rank to the target, then attempt a counteract check against one disease or poison afflicting the target. The target is then temporarily immune for 24 hours. If the target is immune to poison, this spell has no effect.\nHeightened (5th) You can attempt counteract checks against any number of poisons or diseases afflicting the target.","source":{"provider":"PAIZO","sourceId":"CBPcGH1FFDG9vf4Z","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.pyrotechnics","name":"Pyrotechnics","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["fire","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 fire","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You turn a fire into either a burst of blinding fireworks or a thick cloud of choking smoke, chosen when you Cast the Spell. The spell targets one fire source, which is immediately extinguished if it is a non-magical fire the size of a campfire or smaller. If the fire source is a creature, the creature takes 1d6 points of cold damage and is not extinguished.\n\n- Fireworks The targeted fire explodes into a colorful array of flashy, fiery, glowing aerial fireworks in a 20-foot-radius burst. The first time you Sustain the Spell each round, you can cause the area of fireworks to ascend up to 20 feet, but you cannot move the area laterally. Creatures that start their turn within the area of the fireworks must attempt a Fortitude save, and are then temporarily immune for 1 minute.\nCritical Success The creature is unaffected\n\nSuccess The creature is until the end of its next turn.\n\nFailure The creature is until the end of its next turn.\n\nCritical Failure The creature is Blinded for 1 minute.\n\n- Smoke Cloud Thick smoke billows out from the fire and coalesces into a cloud that spreads to fill a 20-foot-radius burst centered on the targeted fire. Creatures within the smoke cloud take a -4 circumstance penalty to visual Perception checks, and creatures outside the smoke cloud take a -4 circumstance penalty to visual Perception checks to detect creatures or objects within it. The first time you Sustain the Spell each round, you can cause the smoke cloud to descend up to 20 feet, but you cannot move the area laterally. Creatures that start their turn within the smoke cloud must attempt a Fortitude save, and are then temporarily immune for 1 minute.\nSuccess The creature is unaffected.\n\nFailure The creature is Sickened 1.\n\nCritical Failure The creature is Sickened 1 and cannot recover from the sickened condition while in the area of the smoke cloud.","source":{"provider":"PAIZO","sourceId":"TUbXnR4RAuYzRx1u","book":"Pathfinder #152: Legacy of the Lost God","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.qi-blast","name":"Qi Blast","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","force","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash your qi as a powerful blast that deals 2d6 force damage. If you use 2 actions to cast qi blast, increase the size of the cone to 30 feet and the damage to 3d6. If you use 3 actions to cast qi blast, increase the cone to 60 feet and the damage to 4d6. Each creature in the area must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is pushed 5 feet.\n\nCritical Failure The creature takes double damage and is pushed 10 feet.\nHeightened (+1) The damage increases by 1d6, or by 2d6 if you use 2 or 3 actions.","source":{"provider":"PAIZO","sourceId":"oo7YcRC2gcez81PV","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.radiant-globe","name":"Radiant Globe","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a dome of brilliant light that destroys projectiles attempting to pass through it. Ammunition from physical ranged attacks—such as arrows, bolts, sling bullets, and other objects of similar size—is destroyed in a flash of light when it passes into or out of the globe's area. Attackers targeting creatures or objects through the globe's surface with physical ranged attacks must succeed at a Fortitude save or become for 1 round ( for 1 round on a critical failure).","source":{"provider":"PAIZO","sourceId":"nXoc5YbcynmhZcQs","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rally-point","name":"Rally Point","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"SQUARE","feet":5}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You mark the area touched as a rally point. During the spell's duration, you can take a single action, which has the concentrate trait, to teleport to the rally point along with items you are wearing or holding. This teleportation fails if the area is occupied, if the rally point is more than 120 feet away, or if you try to bring along any other creature, even if it's in an extradimensional container. Once you teleport to the rally point, the spell's duration ends.\nHeightened (7th) You can designate up to four other creatures within 30 feet, in addition to yourself. Each of these creatures can teleport to the rally point once during the spell's duration by taking a single action, which has the concentrate trait. The spell's duration no longer ends once you teleport to the rally point, though you still can't teleport to the rally point again.","source":{"provider":"PAIZO","sourceId":"98gJvb8Xtn8OLIY7","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rangers-bramble","name":"Ranger's Bramble","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","plant","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause plants in the area to entangle your foes, with the effects of . A creature that critically fails the save takes (max(0,@item.level -1))d4[bleed] damage in addition to being . Escaping your bramble doesn't end the bleed damage.\n\nHeightened (+1) The bleed damage on a critical failure increases by 1d4.","source":{"provider":"PAIZO","sourceId":"KktHf7zIAWOr499h","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ransack-the-night","name":"Ransack the Night","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["darkness"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"blessed salt, citrus fruits (such as yuzu or limes), and rare spices worth 25 gp × the spell rank"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert)","secondaryChecks":"Arcana, Intimidation, or Occultism","secondaryCasters":3},"description":"When Fumeiyoshi was punished by the Celestial Court for deicide and fratricide, the rat who would become Lao Shu Po robbed the cangue-bound Fumeiyoshi of a sizable chunk of his shadow. This fully catalyzed the rat's transformation into Lao Shu Po, the new Tian goddess of night. Ransack the night is a Laoite ritual allowing you to mimic this divine thievery and shroud yourself in the night's cerements.\n\nThis ritual can only be performed at night. You dig narrow troughs into the dirt and toss blessed salt as well as the juice of citrus fruits into these gashes in the ground. Performing this ritual in an area actively haunted by undead or frequented by fiends reduces the DCs of the ritual's skill checks by 2. If the ritual is successful, a smoky black miasma, said to be the blood and tears of Fumeiyoshi himself, emerges from the broken earth to augment and enhance your spiritual aura, helping you to remain undetected by fiends and undead.\nCritical Success Fiends and undead who are 5th level or lower treat you as if you were . If you take a hostile action against a fiend or undead, you lose this concealment against that fiend or undead until the end of your next turn.\n\nSuccess As critical success, but when you lose concealment against a fiend or undead, you don't regain concealment from this ritual against that fiend or undead.\n\nFailure The ritual has no effect.\n\nCritical Failure The miasma occludes your senses instead; for 24 hours, the targets treat fiends and undead as if they were concealed.\nHeightened (+1) Increase the level of affected creatures by 2.","source":{"provider":"PAIZO","sourceId":"ksJFGSGlNpUhwcsp","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reincarnate","name":"Reincarnate","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"rare herbs worth a total value of the target's level (minimum 1) × 25 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 dead creature of up to 8th level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (expert)","secondaryChecks":"Occultism, Religion","secondaryCasters":2},"description":"You call forth the target's soul and attempt to incarnate it into a brand-new body. As the soul won't be returning to the original body, only a small portion of the creature's remains are required. These remains must have been part of the original body at the time of death, and the target must have died within the past week. If Pharasma has decided that the target's time has come or the target's soul is trapped or doesn't wish to return, this ritual automatically fails, but you discover this after you succeed at the Religion check and can end the ritual without paying the cost.\n\nIf the ritual is successful, the target's new body has a random ancestry. Roll [[/r 1d20]]. On a result of 1 through 14, the new body is one of a common ancestry, while on a 15 through 20 they become a member of an uncommon or rare ancestry. The GM chooses possible ancestries based on those found in the region and randomly determines the ancestry. For instance, the GM could roll 1d8 to choose a common ancestry from Player Core. The target replaces their ancestry Hit Points, size, Speeds, attribute boosts and flaws, traits, and special abilities with those of their new ancestry. The target loses their heritage and ancestry feats, selecting replacements from their new ancestry. The target's background, class features, and languages remain unaltered.\nCritical Success You reincarnate the target into a new adult body. This new body has full HP and has the same spells prepared as the original did when it died.\n\nSuccess As critical success, except the new body has 1 HP and no spells prepared. The soul takes some time to adjust to their new body, leaving them Clumsy 2, Drained 2, and Enfeebled 2 for 1 week; these conditions can't be removed or reduced by any means until the week has passed.\n\nFailure You fail to reincarnate the target.\n\nCritical Failure The target's soul becomes trapped in an unintelligent animal creature of the GM's choosing, with a level no greater than half the target's level. While trapped, the target has an Intelligence modifier of –5 and can't use any of their own abilities.\nHeightened (4th) The maximum level of the target increases to 10. The cost is the target's level (minimum 1) × 40 gp.\n\nHeightened (5th) The maximum level of the target increases to 12. The cost is the target's level (minimum 1) × 75 gp.\n\nHeightened (6th) The maximum level of the target increases to 14. The cost is the target's level (minimum 1) × 125 gp. The target must have died within the past month.\n\nHeightened (7th) The maximum level of the target increases to 16. The cost is the target's level (minimum 1) × 200 gp. The target must have died within the past month.\n\nHeightened (8th) The maximum level of the target increases to 18. The cost is the target's level (minimum 1) × 300 gp. The target must have died within the past year.\n\nHeightened (9th) The maximum level of the target increases to 20. The cost is the target's level (minimum 1) × 600 gp. The target must have died within the past decade.","source":{"provider":"PAIZO","sourceId":"gIVaSCrLhhBzGHQY","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.return-the-favor","name":"Return the Favor","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An ally uses a reaction to grant you a beneficial effect during a combat encounter.\n\nYou're unable to leave any debts unpaid. When an ally supports you in a fight, you offer assistance in turn for the favor. The triggering ally gains 12 temporary Hit Points for 1 minute.\n\nHeightened (+1) The temporary Hit Points increase by 4.","source":{"provider":"PAIZO","sourceId":"9gMQPCaFM27PEIh4","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ring-of-truth","name":"Ring of Truth","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":20}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You designate an area in which lies are revealed. Creatures in the area also take a –2 status penalty to Deception checks. Each time a creature in the area speaks a true statement, the soft ring of a bell sounds in the area. Creatures are aware of the magic; therefore, they can avoid answering questions to which they would normally respond with a lie, or they can be evasive as long as they remain within the boundaries of the truth. If a creature is in the area when the spell is cast or later enters the area, that creature attempts a Will save. It uses the results of this initial save if it leaves and reenters the area.\n\nCritical Success The target is so convincing that the bell rings even if they lie.\n\nSuccess If the target lies and succeeds at their Deception check against all targets, the bell still rings.\n\nFailure The bell accurately sees through their deception and will never ring if they lie.","source":{"provider":"PAIZO","sourceId":"aewxsale5xWEPKLk","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.roaring-applause","name":"Roaring Applause","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your flamboyant flourish invokes such powerful feelings in your audience that you incite cheers and applause. Targets of this spell must be able to see, hear, or otherwise understand you. The targets must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target becomes mildly distracted by your display and applauds while it isn't fully occupied. It can't use reactions.\n\nFailure The target applauds you so vigorously that it can't use reactions and is Slowed 1. The applause is so involved that it has the manipulate trait. This triggers reactions based on the manipulate trait at the start of the target's turn.\n\nCritical Failure As failure, plus the target is so distracted by its vigorous applauding of you that it's with you.\n\nHeightened (6th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"czO0wbT1i320gcu9","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rouse-skeletons","name":"Rouse Skeletons","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Misshapen skeletal forms erupt from a solid surface, such as a stone floor, and fill the burst. The area they fill is difficult terrain. Their grasping claws deal 2d6 slashing damage to creatures on the ground in the area when the skeletons first appear with a basic Reflex save.\n\nOn subsequent rounds, the first time you Sustain the Spell each round, you can move the area of skeletons up to 20 feet within the range of the spell and deal 2d6 slashing damage with a basic Reflex save to each creature in the new area.\n\nDamaging or destroying the skeletons is irrelevant, as new bones pull forth from the ground to repair and replace any that are obliterated.\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"0JWyMwVnLxX9CDYQ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.rune-trap","name":"Rune Trap","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"10 minutes"},"cost":"pigments and oils worth a total value of 5 gp x the rank of the spell to be stored"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object or a 10-foot-by-10-foot area","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert), Nature (expert), Occultism (expert), or Religion (expert) as determined by the tradition of spell cast in the ritual","secondaryChecks":"Crafting","secondaryCasters":1},"description":"You create a magical trap by binding a hostile spell into a rune. As part of performing this ritual, you also Cast a Spell to store in the rune. The stored spell must take 3 actions or fewer to cast, have a hostile effect, and target one creature or have an area. You can set a password, a trigger, or both for the rune. Any creature that moves, opens, or touches the target container or enters the target area that doesn't speak the password or that matches the trigger activates the rune, releasing the harmful spell within.\n\nOnce a spell is stored in the rune, the rune gains all the traits of that spell. If the stored spell targets one or more creatures, it targets the creature that set off the rune. If it has an area, that area is centered on the creature that set off the rune. The rune is a magical trap, using your spell DC for both the Perception check to notice it and the Thievery check to disable it; both checks require the creature attempting them to be trained in order to succeed. You can Dismiss the rune you create with this ritual so long as you can see it.\n\nCritical Success You create a particularly effective rune, granting a +2 circumstance bonus to the DC to notice and disable the rune.\n\nSuccess You create the rune successfully.\n\nFailure You fail to create the rune.\n\nCritical Failure The rune backfires, dealing 4d6 force damage per rank of the rune's spell to you, the secondary caster, and all creatures within 10 feet of the ritual's area","source":{"provider":"PAIZO","sourceId":"o0l57UfBm9ScEUMW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.safe-passage","name":"Safe Passage","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 10-foot-wide, 10-foot-tall, 60-foot-long section of terrain\nYou make passage through the area safe for a brief amount of time. Anyone passing through the area gains the following benefits against harmful effects of the terrain and environment, including environmental damage, hazardous terrain, and hazards in the area. The spell grants a +2 status bonus to AC and saves against such effects, and resistance 5 to all damage from such effects. Furthermore, the spell prevents anything in the area that's prone to collapse, such as a rickety bridge or an unstable ceiling, from collapsing, except under extreme strain that would collapse a normal structure of its type.\n\nSafe passage protects only against harm, not inconvenience, and it doesn't reduce difficult terrain, remove the condition caused by precipitation, or the like, nor does it protect against creatures within the spell's area.\n\nHeightened (5th) The granted resistance increases to 10, and the area can be 120 feet long.\n\nHeightened (8th) The granted resistance increases to 15, and the area can be 500 feet long.","source":{"provider":"PAIZO","sourceId":"IFuEzfmmWyNwVbhY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sand-form","name":"Sand Form","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target's body and gear aspects of sand. The target gains resistance 5 to piercing and slashing damage, has no scent, and can't bleed. In sandy terrain, even when out in the open, the target has enough concealment to attempt to Hide. Each time the target takes damage to which sand form grants resistance, reduce the duration of the spell by 1 minute.\n\nHeightened (5th) The resistance is 10.\n\nHeightened (7th) The resistance is 15.","source":{"provider":"PAIZO","sourceId":"KjC2ya8HD5AENeHI","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.scrying-ripples","name":"Scrying Ripples","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","scrying","water"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 gallon of water or more","area":null},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You touch the water's surface, and as the ripples spread out, so do your senses. When you Cast this Spell, you automatically know the location of any unoccupied, flowing water with a surface area of at least 1 square within 500 feet. You can pick any one of these streams to see and hear out of for the duration of the spell, though your field of vision is perpendicular to the flowing surface. For example, you could look normally out of a waterfall but would look straight up from out of a river. Each time you Sustain the spell, you can change to a different water source or move elsewhere along the same one.\n\nIf the water you're scrying through ceases flowing, such as by a faucet turning off, a river damming, or a waterfall freezing over, this spell ends. Additionally, your face appears as a faint reflection in the water's surface as you peek through. A creature that Seeks and succeeds at their Perception check against your spell DC detects your presence in the water.\n\nHeightened (5th) You know the location of and can scry through flowing water within 1 mile.","source":{"provider":"PAIZO","sourceId":"k1apwY0ROoMKlvLt","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sculpt-sound","name":"Sculpt Sound","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["illusion","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature or object","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You change the sounds made by a creature or object. Choose how you're altering the sounds when you Cast the Spell; you can't alter it later. You can cause something that didn't create a sound to make sound, alter the voice of a creature, amplify or deaden a sound, or transform one sound into another. A creature who succeeds at a Perception check against your spell DC can determine that the sound was altered by an illusion, including hearing faint sounds if you deadened the sound, but they can't determine the true sound unless they critically succeed at the Perception check. You can the spell.\n\nBecause this spell obscures sound instead of preventing it, using the spell to quiet a creature doesn't prevent that creature from using verbal spell components, though it does prevent most auditory effects that rely on another creature hearing them accurately. An unwilling target can attempt a Will save.\n\nSuccess The affected sound from the creature isn't altered.\n\nFailure The affected sound from the creature is altered in the way you determine.\n\nCritical Failure The affected sound from the creature is altered and the target becomes Stupefied 2 for 1 minute as it struggles with the disorienting effects of its altered sound.\n\nHeightened (5th) You can target up to 6 creatures or 6 objects, altering the sounds of all affected creatures or objects in the same way.","source":{"provider":"PAIZO","sourceId":"HHGUBGle4OjoxvNR","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sea-of-thought","name":"Sea of Thought","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{},"areaFeet":5},"counteraction":false,"ritual":null,"description":"You cover the area in a sloshing torrent of semi-solidified thought, roughly ankle high. The area becomes difficult terrain, similarly to a shallow bog. Each round that a creature starts its turn in the area, it must attempt a Fortitude save against the shifting waves of thought. On a failure, it takes a –10-foot circumstance penalty to its Speeds until it leaves the area, and on a critical failure, it is also knocked .\nHeightened (+1) The radius of the spell's area increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"tSosbMsftXcRaQgT","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.secret-page","name":"Secret Page","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 page up to 3 square feet in size","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You change the target's text to different text entirely. If the text is a spellbook or a scroll, you can change it to show a spell you know of secret page's level or lower. The replacement spell cannot be cast or used to prepare a spell. You can also transform the text into some other text you have written or have access to. You can specify a password that allows a creature touching the page to change the text back and forth. You must choose the replacement text and the password, if any, when you Cast the Spell.","source":{"provider":"PAIZO","sourceId":"VVAZPCvd4d90qVA1","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.secure-siege-weapons","name":"Secure Siege Weapons","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"2 hours"}},"targeting":{"range":{"kind":"NONE"},"target":"siege weapons operated by allied crews","area":{"shape":"BURST","feet":250}},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (expert) or Warfare Lore (expert)","secondaryChecks":"Engineering Lore","secondaryCasters":1},"description":"You strengthen your army's siege weapons and prevent them from being commandeered by enemy hands. At the successful conclusion of the ritual, each allied siege weapon in the area gains an increase to its Hardness and Hit Points for the duration. In addition, enemies who try to operate or move an affected mounted siege weapon or pick up an affected portable siege weapon must succeed at a will saving throw or be forced to roll twice and take the worse result on any check to Load or Strike with the siege weapon; this is a misfortune effect. Finally, if an enemy Launches an affected siege weapon, their targets can roll twice and take the better result for any resulting saving throw; this is a fortune effect.\nCritical Success Each affected siege weapon's Hardness increases by 10, and its maximum Hit Points increase by an amount equal to three times the siege weapon's level.\n\nSuccess Each affected siege weapon's Hardness increases by 5, and its maximum Hit Points increase by an amount equal to twice the siege weapon's level.\n\nFailure The ritual has no effect.\n\nCritical Failure All allied siege weapons in the area gain the broken condition.","source":{"provider":"PAIZO","sourceId":"a9og2ZYfr8kAeltU","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.seed-of-mercy","name":"Seed of Mercy","kind":"RITUAL","rank":3,"rarity":"RARE","traits":["trial"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"potent medicine valued at 200 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Medicine (expert)","secondaryChecks":"Nature, Religion","secondaryCasters":1},"description":"The gods who value benevolence and the caretaking of small and vulnerable beings also value those qualities in the mortal adventurers who journey through the lands of Tian Xia. You demonstrate your willingness to aid even the most helpless of life by nursing a small, injured bird to health and allowing it to fly away to freedom, earning in return the protection of the natural world. If you're able to nurse the bird to health, it will return to you with a seed, which will grow into a sprout bearing a single flower.\n\nThe sprout withers if you don't personally water it with at least 1 Bulk of pure spring water a day or if it's left unattended in dangerous circumstances. It's anathema to this ritual to let the sprout wither, and doing so immediately ends its benefits. If the ritual is ended in this way, you must conduct an ritual before attempting this ritual again.\n\nCritical Success As success, except the sprout also grows a single fruit after you've cared for it for a week. Removing the fruit causes the sapling to wither, but the fruit can be eaten as a Moderate Healing Potion.\n\nSuccess You nurse the bird to health. It returns to you with a seed that, when planted and watered, grows into a sprout with a single flower. Once you've cared for it for a week, you gain the feat. If you lose Toughness due to violating the ritual's anathema, you lose a number of Hit Points equal to the decrease in your maximum Hit Points.\n\nFailure You aren't able to heal the bird, but you help its passing to be as painless as possible.\n\nCritical Failure Your attempt to heal the bird causes greater suffering. Another bird brings you a seed that, if planted, will grow into a gourd that releases a small demon to attack you.","source":{"provider":"PAIZO","sourceId":"opXqASAY37ltENB8","book":"Pathfinder Lost Omens Tian Xia World Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-projectile","name":"Shadow Projectile","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["illusion","manipulate","shadow","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"3d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"Trigger An ally within 20 feet of you makes a ranged attack roll.\n\nYou create an illusory duplicate of your ally's ranged attack to confuse your opponents. You launch an illusory double of your ally's projectile or spell at the same target, leaving the enemy unsure which attack to avoid. The target takes 3d8 mental damage, depending on its Will save. Regardless of the result of its save, it's temporarily immune to shadow projectile spells for 1 hour.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is against the triggering attack.\n\nFailure The creature is off-guard against the triggering attack and takes full damage from your illusory projectile.\n\nCritical Failure As failure, but double damage.\n\nHeightened (+2) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"8cuqRFB3mWBOgy61","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shadow-spy","name":"Shadow Spy","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You mix blood, soil, and shadow together to form a half-real homunculus in the shape of a crow, sparrow, or other bird. You then command the bird to fly to a location within range and observe all around it. The bird has the statistics of a , save that it has all of your senses and shares your Perception modifier. Once the spell's duration elapses or upon a trigger you set (which must be fairly simple—\"at dusk\" or \"when the judge leaves\"), the bird flies to your location. If you wring its neck and drink its blood, you learn all that it saw since its creation.","source":{"provider":"PAIZO","sourceId":"aq76wpgsVEENDyau","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shared-invisibility","name":"Shared Invisibility","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["aura","illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"you and up to 5 willing creatures","area":{"shape":"EMANATION","feet":30}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and all targets are except to each other as long as the targets remain within the emanation. If a creature made invisible by this spell leaves the spell's area, it becomes visible and remains so even if it returns to the spell's area. If any creature made invisible by this spell uses a hostile action, the spell ends after the hostile action is completed.\nHeightened (5th) The targets increase to you and up to 10 willing creatures. The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"I0j56TNRmGcTyoqJ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shatter-mind","name":"Shatter Mind","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","mental","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"wutn1oqihzg6kr0d","formula":"3d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"wutn1oqihzg6kr0d":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You telepathically assail the minds of your foes. You deal 3d4 mental damage to all enemies in the area, with a basic Will save.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"BqJAOPimCq5uCcEJ","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.sheltering-wings","name":"Sheltering Wings","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"REACTION"},"requirements":"An ally moves through a square within 15 feet of you or uses an action that has the move trait."},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"1 ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An ally moves through a square within 15 feet of you or uses an action that has the move trait.\n\nLike migratory birds, you know everyone flies farther together. You cause immense wings to sprout from your familiar. Your familiar Flies up to 30 feet, though it must move toward the triggering ally. If your familiar ends this movement adjacent to the triggering ally, it lands on their back; until the beginning of your next turn, the familiar automatically is carried by the ally, and its wings provide them cover. When the spell ends, the familiar hops off your ally into an adjacent square.","source":{"provider":"PAIZO","sourceId":"gxK5XW4WAXOgY1mN","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shift-blame","name":"Shift Blame","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the target of the triggering attack or skill check","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or another creature attacks a creature or fails at a Deception, Diplomacy, or Intimidation check.\n\nYou alter the target's memories of the triggering event as they form. You choose another creature (which can be you) with the capacity to make the triggering attack or skill check, and you alter the target's memories to recall the creature you chose as responsible for the triggering attack or skill check. The target must attempt a Will save and is then temporarily immune for 24 hours.\n\nCritical Success The target knows you attempted to alter its memories.\n\nSuccess The target doesn't realize you attempted to alter its memories, though it knows you cast a spell.\n\nFailure You successfully alter the target's memory. It isn't forced to react to the new memories in a particular way, and it's likely to question them if they contradict other information it knows or are implausible for the situation.","source":{"provider":"PAIZO","sourceId":"lONs4r14LEBZRLLw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shifting-sand","name":"Shifting Sand","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":20,"text":"a horizontal earthen or sandy surface within a 20-foot burst"}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Area (continued) a horizontal earthen or sandy surface within a 20-foot burst\nYou cause the surface to heave. The area becomes difficult terrain, and any tracks in the area are destroyed by the churning ground. Creatures standing in the area take a –1 status penalty to Acrobatics checks to and and Athletics checks to and . The first time each round you Sustain the Spell, you can move the churning area up to 20 feet in any direction. Creatures by the spell are carried along with the shifting sand in the same direction, if possible. Creatures that enter or begin their turn standing in the shifting sand must attempt a Reflex save.\nCritical Success The creature is unaffected and ignores the area's difficult terrain and penalty to skill checks until the end of its turn.\n\nSuccess The creature ignores the area's penalty to skill checks until the end of its turn.\n\nFailure The creature is affected normally by the spell this turn.\n\nCritical Failure The creature becomes immobilized within the spell's area until it Escapes. If the creature was already immobilized by shifting sand, it also falls .\nHeightened (5th) The status penalty increases to –2, and the spell's range increases to 60 feet.\n\nHeightened (7th) The status penalty increases to –3, the spell's range increases to 60 feet, and the spell's area increases to a 30-foot burst.\n\nHeightened (9th) The status penalty increases to –4, the spell's range increases to 60 feet, and the spell's area increases to a 40-foot burst.","source":{"provider":"PAIZO","sourceId":"HcIAQZjNXHemoXSU","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.show-the-way","name":"Show the Way","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","detection","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and allies in the area gain preternatural knowledge of the path ahead, allowing you to intuit the best way forward and avoid potential obstacles, such as difficult or confusing terrain. For the purpose of long-distance overland travel during exploration mode, traveling through difficult terrain reduces you to only three-quarters your travel Speed instead of half, and traveling through greater difficult terrain reduces your travel Speed to only half your travel Speed instead of one-third. Show the way doesn't prevent you from falling into traps or encountering other artificial obstacles and hazards.\nHeightened (6th) For the purpose of long-distance overland travel during exploration mode, traveling through difficult terrain doesn't reduce your travel Speed at all, and traveling through greater difficult terrain reduces your travel Speed to only three-quarters of its normal value instead of one-third.","source":{"provider":"PAIZO","sourceId":"ThE5zPYKF4weiljj","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shrink-item","name":"Shrink Item","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 non-magical object up to 20 cubic feet in volume and up to 80 Bulk","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shrink the target to roughly the size of a coin with negligible Bulk. You can Dismiss the spell, and the spell ends if you toss the object onto a solid surface. The object can't be used to attack or cause damage during the process of it returning to normal size. If there isn't room for the object to return to normal size when the spell ends, the spell's duration continues until the object is in a location large enough to accommodate its normal size.","source":{"provider":"PAIZO","sourceId":"kWh8sJH7yawidMyW","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shrink-the-span","name":"Shrink the Span","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","manipulate","monk","teleportation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TEXT","text":"see text"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You move so fast you blur across planar boundaries. You teleport up to a distance equal to your Speed within your line of sight.","source":{"provider":"PAIZO","sourceId":"Az3PmWnlWSb5ELX9","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shroud-of-flame","name":"Shroud of Flame","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You encircle yourself in an aura of protective flames. Each creature that hits you with an unarmed attack, Grapples you, or otherwise touches you takes 3[fire] damage. When you Cast the Spell and the first time you sustain it each round, each creature in the area takes 3d6[fire] damage (basic Reflex save).\n\nHeightened (+1) The damage caused by touching you increases by 1, and the fire damage when you Cast the Spell or sustain it increases by 1d6.","source":{"provider":"PAIZO","sourceId":"Q1OWufw6dUiY8yEI","book":"Pathfinder #168: King of the Mountain","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.sign-of-conviction","name":"Sign of Conviction","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"j2ds5suvw51ucg4c","formula":"2d10","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"j2ds5suvw51ucg4c":"1d10"}},"counteraction":false,"ritual":null,"description":"You conjure the religious symbol of your deity into the air above you in the same space you stand in, wielding the power of your faith to smite your foes. This religious symbol is immobile, made of pure magical force, and can't be damaged. As long as you Sustain sign of conviction, you gain a +1 status bonus to AC and saving throws and are . The DC for any effect to force you to move out of your space (such as the action) is equal to your spell DC or the normal DC, whichever is higher. If you stop being immobilized or are moved out of your space, sign of conviction immediately ends.\n\nWhen you Cast the Spell and each time you Sustain the Spell, the religious symbol emits a blast of energy at a target within 100 feet. Make a spell attack roll that deals 2d10 damage on a success (see below for determining damage type) and double damage on a critical success. You can Sustain the Spell multiple times in the same round to emit an array of blasts.\n\nIf you worship a good deity, the spell gains the good and light traits, deals your choice of either fire or spirit damage, and emits bright light in a . If you worship an evil deity, the spell gains the evil and darkness traits, deals your choice of cold or spirit damage, and reduces the light level in a to dim light if it would be brighter. If you worship a neutral deity, the spell gains the force trait and deals force damage.\n\nHeightened (+2) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"SxRVCc1Q2MtVuPMo","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.slow","name":"Slow","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You dilate the flow of time around the target, slowing its actions.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Slowed 1 for 1 round.\n\nFailure The target is Slowed 1 for 1 minute.\n\nCritical Failure The target is Slowed 2 for 1 minute.\n\nHeightened (6th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"WsUwpfmhKrKwoIe3","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.song-of-marching","name":"Song of Marching","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","concentrate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 hour","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You maintain a brisk performance that keeps allies on the move. You and your allies in the area can for the spell's duration, in addition to your other exploration activities (your exploration activity is Sustaining this spell). You and your allies then become temporarily immune for 1 day.\n\nIf you enter an encounter while performing this song, you can use your Performance modifier for the initiative roll. You and your affected allies also receive a +1 status bonus to that initiative roll.\n\nHeightened (6th) You can Sustain the Spell for up to 2 hours.\n\nHeightened (9th) You can Sustain the Spell for up to 4 hours.","source":{"provider":"PAIZO","sourceId":"LTUaK3smfm5eDiFK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.soothing-blossoms","name":"Soothing Blossoms","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Blossoms grow from the ground in a small area, soothing away afflictions and persistent pains and harm. When any creature in that area rolls a successful save against a poison or disease effect, it gets a critical success instead. The blossoms grant assisted recovery to everyone in the area to end their persistent damage, both when the spell is cast and at the start of each of your turns. Once the duration ends, the flowers lose their magical effect, but a few of them might survive in the area as long as they can naturally. This spell doesn't give a benefit on a save against an affliction unless the stage lasts 10 minutes or less.","source":{"provider":"PAIZO","sourceId":"5XUn9NADr05IyiVw","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sparkleskin","name":"Sparkleskin","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You coat a creature's body in a layer of brilliantly sparkling glitter. The target gains a +2 status bonus on Deception checks to and to , and on Performance checks to that have the visual trait. When the target take damage, glitter bursts out of its wound in a . Creatures in the area must attempt a Fortitude save.\n\nFailure The creature is for 1 round.\n\nCritical Failure The creature is dazzled for 3 rounds.","source":{"provider":"PAIZO","sourceId":"KAWQ5x2j4tUJ91ry","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.speak-with-plants","name":"Speak with Plants","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can ask questions of and receive answers from plants and fungi, but the spell doesn't make them more friendly or intelligent than normal. Most normal plants and fungi have a distinctive view of the world around them, so they don't recognize details about creatures or know anything about the world beyond their immediate vicinity. Cunning plant or fungus monsters are likely to be terse and evasive, while less intelligent ones often make inane comments.\n\nHeightened (4th) The duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"qvwIwJ9QBihy8R0t","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spirit-veil","name":"Spirit Veil","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","illusion","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw an occluding veil of spirits around yourself, blocking yourself especially well from undead eyes. You become to all creatures, and you are from undead creatures regardless of what precise senses they have; this grants the effects of , but against all the undead creature's precise senses. If you physically with an undead creature or use a hostile action, the spell ends.\n\nHeightened (+1) You can target one additional willing creature within 30 feet. The spell ends if any target physically Interacts with an undead creature or uses a hostile action.","source":{"provider":"PAIZO","sourceId":"pQ3NIzZXeIIcU81C","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.steal-shadow","name":"Steal Shadow","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","shadow","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"3d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You steal a creature's shadow, leaving it weakened and vulnerable. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Enfeebled 1 for 1 round.\n\nFailure The target takes 3d4[void] damage and is Enfeebled 1 for the spell's duration as you tear its shadow away, collecting it in your hand. On subsequent rounds, the first time each round you Sustain the Spell, you can throttle the shadow to deal 3d4[void] damage to the target (basic Fortitude save). Until the spell ends, the target doesn't cast a shadow.\n\nCritical Failure As failure, but the target is Enfeebled 2.\n\nHeightened (+1) The damage when the spell is cast and when it is sustained increases by 1d4[void].","source":{"provider":"PAIZO","sourceId":"0chL1b4OFIZxpN3v","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}}]
